L["ABOUT_TEXT"] = "LazyGCore schlägt deine nächste Fähigkeit anhand recherchierter Prioritätslisten für World of Warcraft: Forever für alle neun Klassen vor und leitet deine Talentwahl.\n\nForever läuft auf der modernen WoW-Engine, die Addons einige Kampfinformationen vorenthält (Gesundheit des Ziels, manche Auren, das Kampflog). LazyGCore liest alles über eine Schicht, die sicher mit geheimen Werten umgeht: Verbirgt das Spiel einen Wert, greift LazyGCore auf seine eigene Zauberverfolgung oder Blizzards reaktive 'benutzbar'-Prüfungen zurück, statt zu raten.\n\nWirkt ein Vorschlag einmal falsch, stelle die Engine auf 'LazyGCore + Blizzard als Ersatz' oder 'Blizzard-Kampfassistent' um und nutze /lazygcore check und /lazygcore status, um zu melden, was dein Client anzeigt.\n\nBefehle: /lazygcore, /lazygcore talents, /lazygcore toggle, /lazygcore spec <name / auto>, /lazygcore engine <lazygcore / hybrid / blizzard>."

