L["Your game client has no font for the chosen language, so some text may show as boxes. Choose Auto or English on the Language page."] = "Dein Spielclient hat keine Schriftart für die gewählte Sprache, daher kann manche Schrift als Kästchen erscheinen. Wähle Auto oder Englisch auf der Seite Sprache."
