L["Talent spec switched - spec override reset to Auto."] = "Talentspezialisierung gewechselt - erzwungene Spezialisierung auf Automatisch zurückgesetzt."

-- Mage / Warlock / Druid rotation fixes (r9)
L["New Fireball rank: hits harder than your Frostbolt."] = "Neuer Feuerball-Rang: trifft härter als dein Frostblitz."
L["Conjure Mana Ruby"] = "Manarubin herbeizaubern"
L["Conjure Mana Citrine"] = "Manacitrin herbeizaubern"
L["Conjure Mana Jade"] = "Manajadestein herbeizaubern"
L["Conjure Mana Agate"] = "Manaachat herbeizaubern"
L["No mana gem in your bags."] = "Kein Manaedelstein in deinen Taschen."
L["Remove Lesser Curse"] = "Geringen Fluch aufheben"
L["Remove the curse on you."] = "Entferne den Fluch auf dir."
L["Melee player on you: damage + 50% daze, then step away."] = "Nahkampfspieler an dir: Schaden + 50% Benommenheit, dann zurücktreten."
L["R3 with Ice Shards 5 + Piercing Ice 3: beats Fireball."] = "Rang 3 mit Eissplitter 5 + Stechendes Eis 3: stärker als Feuerball."
L["Curses"] = "Flüche"
L["Curse:"] = "Fluch:"
L["None (Banes only)"] = "Keiner (nur Omen)"
L["Your Curse slot: +10% magic damage taken."] = "Dein Fluchplatz: +10% erlittener Magieschaden."
L["Your Curse slot: armor down for the group (target ignores Fear)."] = "Dein Fluchplatz: weniger Rüstung für die Gruppe (Ziel ignoriert Furcht)."
L["Your Curse slot: slower casts."] = "Dein Fluchplatz: langsameres Zaubern."
L["Your Curse slot: less physical damage."] = "Dein Fluchplatz: weniger körperlicher Schaden."
L["Your Curse slot: 30% slow."] = "Dein Fluchplatz: 30% Verlangsamung."
L["Healthstone"] = "Gesundheitsstein"
L["Low health: instant heal (shared 2 min cooldown)."] = "Wenig Gesundheit: sofortige Heilung (gemeinsame Abklingzeit 2 Min.)."
L["No Healthstone in your bags (costs a Soul Shard)."] = "Kein Gesundheitsstein in deinen Taschen (kostet einen Seelensplitter)."
L["Dungeons before Master Demonologist: Blood Pact + Firebolt."] = "Dungeons vor Meister der Dämonologie: Blutpakt + Feuerblitz."
L["Low health: Bear, then Frenzied Regeneration."] = "Wenig Gesundheit: Bär, dann Rasende Regeneration."
L["Hard-hitting filler with Improved Starfire."] = "Starker Füllzauber mit Verbessertem Sternenfeuer."
L["Threat on every mob, less damage taken."] = "Bedrohung auf jedem Gegner, weniger erlittener Schaden."

L["Cheetah / Pack is on in combat: every hit dazes you."] = "Gepard / Rudel ist im Kampf aktiv: jeder Treffer macht dich benommen."
L["You have aggro - drop threat."] = "Du hast Aggro - Bedrohung senken."
L["Melee: more dodge, and dodges enable Mongoose Bite."] = "Nahkampf: mehr Ausweichen, und Ausweichen ermöglicht Mungobiss."
L["Group health hidden - mouse over who to heal"] = "Gruppengesundheit verborgen - fahre mit der Maus über den, den du heilen willst"
L["Immune to attacks and spells for 6-8s, but you can't attack; Forbearance after."] = "Immun gegen Angriffe und Zauber für 6-8 Sek., aber du kannst nicht angreifen; danach Vorahnung."
L["Hard hits incoming: +30% block for 10s."] = "Harte Treffer kommen: +30% Blocken für 10 Sek."
L["+30% block; every block deals Holy damage and threat to the pack."] = "+30% Blocken; jeder Block verursacht Heiligschaden und Bedrohung am Rudel."
L["Instant damage between Auto Shots."] = "Sofortschaden zwischen automatischen Schüssen."
L["Out of melee: sting it while you close in."] = "Außerhalb des Nahkampfs: Biss setzen, während du heranläufst."
L["Hit plus a Fire DoT."] = "Treffer plus Feuer-DoT."
L["One more DoT while the target lives long enough."] = "Ein DoT mehr, solange das Ziel lange genug lebt."
L["Heal up between pulls."] = "Zwischen Pulls heilen."
L["Pack is down - back to Cat."] = "Gruppe liegt - zurück in Katzengestalt."
L["You tank this group: Bear Form."] = "Du tankst diese Gruppe: Bärengestalt."
L["Feral in groups:"] = "Wilder Kampf in Gruppen:"
L["Bear (tank)"] = "Bär (Tank)"
L["Cat (damage)"] = "Katze (Schaden)"
L["Pool energy for Ghostly Strike."] = "Energie für Geisterhafter Stoß sammeln."
L["Renew yourself: heals over 15s while you keep casting."] = "Erneuerung auf dich: heilt 15 Sek. lang, während du weiterzauberst."
L["Instant hit plus a 12s Fire DoT."] = "Sofortiger Treffer plus 12 Sek. Feuerschaden über Zeit."
L["Regrowth is ticking - Healing Touch for the rest."] = "Nachwachsen tickt - Heilende Berührung für den Rest."
L["Low health: absorb the next hits."] = "Wenig Gesundheit: die nächsten Treffer absorbieren."
L["Your main nuke."] = "Dein Hauptzauber für Schaden."
L["Damage and a 40% slow on everything in front of you."] = "Schaden und 40% Verlangsamung für alles vor dir."
L["Shadow DoT: keep it ticking."] = "Schatten-DoT: dauerhaft aufrechterhalten."
L["Channeled: hits everything in the area for 6s."] = "Kanalisiert: trifft 6 Sek. lang alles im Bereich."
L["At your feet: Fire damage to every mob within 10 yd."] = "Zu deinen Füßen: Feuerschaden an allen Gegnern im Umkreis von 10 Metern."
L["At your feet: burns the first mob to reach it."] = "Zu deinen Füßen: verbrennt den ersten Gegner, der sie erreicht."
L["Weapon-damage kick, 8s cooldown (+30% run speed)."] = "Tritt mit Waffenschaden, 8 Sek. Abklingzeit (+30% Laufgeschwindigkeit)."
L["21s bleed: keep it on targets that live."] = "21 Sek. Blutung: auf Zielen halten, die länger leben."
L["Single target: your hardest-hitting shot."] = "Einzelziel: dein stärkster Schuss."
L["Hits up to 4 enemies around you."] = "Trifft bis zu 4 Gegner um dich herum."
L["Open with Charge, then Berserker Stance."] = "Mit Sturmangriff eröffnen, dann Berserkerhaltung."
L["Before Whirlwind (36) Fury fights here: Rend and Overpower."] = "Vor Wirbelwind (36) kämpft Furor hier: Verwunden und Überwältigen."
L["Pool energy for Backstab."] = "Energie für Meucheln sammeln."
L["In danger: quick heal on yourself."] = "In Gefahr: schnelle Heilung auf dich selbst."
L["Hurt: Renew yourself and keep casting."] = "Verletzt: Erneuerung auf dich und weiterzaubern."
L["Shadowform filler."] = "Füller in Schattengestalt."
L["Filler: out-damages the wand."] = "Füller: macht mehr Schaden als der Zauberstab."
L["Group health hidden: a cheap heal on the tank (mouse over whoever needs it)."] = "Gruppengesundheit verborgen: eine günstige Heilung auf den Tank (fahre mit der Maus über den, der sie braucht)."
-- ============================================================================
-- OPTION TOOLTIPS (hover explanations of the options window controls)
-- ============================================================================
L["Turns LazyGCore on or off. Off hides the display and stops all suggestions, action bar glows, alerts and sounds."] = "Schaltet LazyGCore ein oder aus. Aus blendet die Anzeige aus und stoppt alle Vorschläge, das Leuchten auf der Aktionsleiste, Warnungen und Töne."
L["Keeps the display where it is. While locked the icon ignores the mouse, so clicks pass through to the game; unlock it to drag the display somewhere else."] = "Hält die Anzeige an ihrem Platz. Gesperrt ignoriert das Symbol die Maus, Klicks gehen also ans Spiel durch; entsperre sie, um die Anzeige woandershin zu ziehen."
L["Shows the LazyGCore button on the minimap. Click: these options. Ctrl+Click: show or hide the display. Shift+Click: Stats window. Alt+Click: talents."] = "Zeigt den LazyGCore-Button an der Minikarte. Klick: diese Optionen. Strg+Klick: Anzeige ein- oder ausblenden. Shift+Klick: Statistikfenster. Alt+Klick: Talente."
L["Where the suggestions come from. LazyGCore priorities: LazyGCore's own rotation for your spec. LazyGCore + Blizzard fallback: LazyGCore first, and only when LazyGCore has nothing to suggest, Blizzard's Assisted Combat pick is shown. Blizzard Assisted Combat: Blizzard's pick on the main icon, LazyGCore's next spells in the queue."] = "Woher die Vorschläge kommen. LazyGCore-Prioritäten: LazyGCores eigene Rotation für deine Spezialisierung. LazyGCore + Blizzard als Ersatz: zuerst LazyGCore, und nur wenn LazyGCore nichts vorzuschlagen hat, wird der Vorschlag des Blizzard-Kampfassistenten gezeigt. Blizzard-Kampfassistent: Blizzards Vorschlag auf dem Hauptsymbol, LazyGCores nächste Zauber in der Warteschlange."
L["Which spec's rotation LazyGCore follows on this character. Auto picks the talent tree with the most points (the Leveling rotation before you spend any). Pick a spec to force it; it goes back to Auto when you switch talent specs."] = "Welcher Spezialisierung LazyGCore auf diesem Charakter folgt. Auto nimmt den Talentbaum mit den meisten Punkten (vor dem ersten Punkt die Leveln-Rotation). Wähle eine Spezialisierung, um sie zu erzwingen; beim Wechsel der Talentspezialisierung geht es zurück auf Auto."
L["Shows the rotation display. Off hides it (with its alerts) everywhere, even in combat, while the action bar glow keeps following the suggestions. Same as /lazygcore toggle."] = "Zeigt die Rotationsanzeige. Aus blendet sie (samt Warnungen) überall aus, auch im Kampf, während das Leuchten auf der Aktionsleiste den Vorschlägen weiter folgt. Wie /lazygcore toggle."
L["Keeps the display on screen out of combat too. Off (default): it shows in combat, plus the two cases below."] = "Lässt die Anzeige auch außerhalb des Kampfes sichtbar. Aus (Standard): Sie erscheint im Kampf und in den zwei Fällen unten."
L["Out of combat, also show the display while you target an enemy, so you see the opener before the pull. Only applies when Show out of combat is off."] = "Außerhalb des Kampfes die Anzeige auch zeigen, solange du einen Gegner im Ziel hast, damit du den Eröffner vor dem Pull siehst. Gilt nur, wenn Außerhalb des Kampfes anzeigen aus ist."
L["Out of combat, also show the display when it suggests a missing buff, pet, poison or weapon imbue, and hide it again once done. Only applies when Show out of combat is off and Suggest buffs & pets (Combat page) is on."] = "Außerhalb des Kampfes die Anzeige auch zeigen, wenn sie einen fehlenden Buff, Begleiter, ein Gift oder eine Waffenverzauberung vorschlägt, und danach wieder ausblenden. Gilt nur, wenn Außerhalb des Kampfes anzeigen aus und Buffs & Begleiter vorschlagen (Seite 'Kampf') an ist."
L["Out of combat, hide the display while there is nothing to suggest instead of showing the LazyGCore logo. Only applies when Show out of combat is on."] = "Außerhalb des Kampfes die Anzeige ausblenden, solange es nichts vorzuschlagen gibt, statt das LazyGCore-Logo zu zeigen. Gilt nur, wenn Außerhalb des Kampfes anzeigen an ist."
L["Shows the spell part of the display: main icon, cooldown icon, history, queue, spell name and reason. Off hides those; the ring (swing timer), warning line, alerts, buff tracker and DPS strip stay, and the action bar glow still works."] = "Zeigt den Zauberteil der Anzeige: Hauptsymbol, Abklingzeit-Symbol, Verlauf, Warteschlange, Zaubername und Begründung. Aus blendet diese aus; Ring (Swing-Timer), Warnzeile, Warnungen, Buff-Tracker und DPS-Leiste bleiben, und das Leuchten auf der Aktionsleiste funktioniert weiter."
L["Color of the ring around the main icon, the DPS strip accent and the Auto action bar glow. Auto (Match Spec) uses your spec's color."] = "Farbe des Rings um das Hauptsymbol, des Akzents der DPS-Leiste und des Auto-Leuchtens auf der Aktionsleiste. Auto (Spezialisierung) nutzt die Farbe deiner Spezialisierung."
L["Look of LazyGCore's windows: these options, the Stats window and the talent windows. Default is the classic WoW gold style."] = "Aussehen von LazyGCores Fenstern: diese Optionen, das Statistikfenster und die Talentfenster. Standard ist der klassische WoW-Goldstil."
L["Size of the whole rotation display: icons, text and DPS strip. Does not change LazyGCore's windows. Default 1.0."] = "Größe der gesamten Rotationsanzeige: Symbole, Text und DPS-Leiste. Ändert LazyGCores Fenster nicht. Standard 1.0."
L["Size of the main spell icon in pixels, before Scale. The cooldown icon grows with it. Default 72."] = "Größe des Hauptsymbols in Pixeln, vor der Skalierung. Das Abklingzeit-Symbol wächst mit. Standard 72."
L["Opacity of the whole rotation display: icons, text, warning line, alerts and DPS strip. 1 = fully visible."] = "Deckkraft der gesamten Rotationsanzeige: Symbole, Text, Warnzeile, Warnungen und DPS-Leiste. 1 = voll sichtbar."
L["Opacity of the spell icons only: the main icon and its ring, the cooldown icon, the spell history and the queue (NEXT). The text stays fully visible."] = "Deckkraft nur der Zaubersymbole: Hauptsymbol mit Ring, Abklingzeit-Symbol, Zauberverlauf und Warteschlange (WEITER). Der Text bleibt voll sichtbar."
L["Dark box behind the rotation display. 0 (default) = no box; higher = a more solid box."] = "Dunkler Kasten hinter der Rotationsanzeige. 0 (Standard) = kein Kasten; höher = deckenderer Kasten."
L["Moves the rotation display back to its default spot below the middle of the screen."] = "Setzt die Rotationsanzeige zurück an ihren Standardplatz unterhalb der Bildschirmmitte."
L["Sets Spec template back to Auto and detects your spec from your talents again."] = "Setzt die Spezialisierungsvorlage zurück auf Auto und erkennt deine Spezialisierung erneut anhand deiner Talente."
L["Opens or closes the floating Stats window (DPS, parse estimate, live stats)."] = "Öffnet oder schließt das schwebende Statistikfenster (DPS, Parse-Schätzung, Live-Werte)."
L["Opens or closes the Talent Guide window with the recommended talent build for your spec."] = "Öffnet oder schließt den Talentratgeber mit dem empfohlenen Talent-Build für deine Spezialisierung."
L["Shows the key bound to the suggested spell in the top-right corner of the main icon, read from your action bars."] = "Zeigt die Taste des vorgeschlagenen Zaubers oben rechts im Hauptsymbol, ausgelesen aus deinen Aktionsleisten."
L["Shows a gold star in the top-left corner of the main icon when the suggestion comes from a proc."] = "Zeigt einen goldenen Stern oben links im Hauptsymbol, wenn der Vorschlag von einem Proc kommt."
L["Shows 'Out of Range' over the main icon and greys it out when your target is out of range of the suggested spell."] = "Zeigt 'Außer Reichweite' über dem Hauptsymbol und graut es aus, wenn dein Ziel außer Reichweite des vorgeschlagenen Zaubers ist."
L["Shows a badge with the enemy count in the bottom-left corner of the main icon when enough enemies are near for AoE."] = "Zeigt unten links im Hauptsymbol ein Abzeichen mit der Gegneranzahl, wenn genug Gegner für AoE in der Nähe sind."
L["Shows the global cooldown sweep over the main icon after each cast. Off by default."] = "Zeigt nach jedem Zauber die globale Abklingzeit als Animation über dem Hauptsymbol. Standardmäßig aus."
L["Healers: shows the name of the group member a heal is suggested for at the bottom of the main icon (not for yourself or your target)."] = "Heiler: zeigt unten im Hauptsymbol den Namen des Gruppenmitglieds, für das eine Heilung vorgeschlagen wird (nicht für dich selbst oder dein Ziel)."
L["Shows a smaller icon right of the main icon for your next major cooldown, racial or on-use trinket: green pulse when ready, grey while it recharges. Off: cooldowns go into the queue instead."] = "Zeigt rechts neben dem Hauptsymbol ein kleineres Symbol für deine nächste große Abklingzeit, Volksfähigkeit oder dein Benutzen-Schmuckstück: grünes Pulsieren wenn bereit, grau während der Abklingzeit. Aus: Abklingzeiten kommen stattdessen in die Warteschlange."
L["Size of the cooldown icon compared to the main icon (0.65 = 65%). Only applies when Cooldown icon is on."] = "Größe des Abklingzeit-Symbols im Vergleich zum Hauptsymbol (0.65 = 65%). Gilt nur, wenn Abklingzeit-Symbol an ist."
L["Shows your last casts as small icons left of the main icon (PREV), newest nearest to it."] = "Zeigt deine letzten Zauber als kleine Symbole links neben dem Hauptsymbol (ZURÜCK), der neueste am nächsten dran."
L["How many past casts to show. Only applies when Spell history is on."] = "Wie viele vergangene Zauber gezeigt werden. Gilt nur, wenn Zauberverlauf an ist."
L["Size of the history icons in pixels. Only applies when Spell history is on."] = "Größe der Verlaufssymbole in Pixeln. Gilt nur, wenn Zauberverlauf an ist."
L["On (default): history, main icon, cooldown icon and queue sit in one row. Off: the classic layout with the queue under the spell name."] = "An (Standard): Verlauf, Hauptsymbol, Abklingzeit-Symbol und Warteschlange stehen in einer Reihe. Aus: das klassische Layout mit der Warteschlange unter dem Zaubernamen."
L["Shows the spells LazyGCore expects to suggest after the current one (NEXT)."] = "Zeigt die Zauber, die LazyGCore nach dem aktuellen voraussichtlich vorschlägt (WEITER)."
L["How many upcoming spells to show. Only applies when Priority queue is on."] = "Wie viele kommende Zauber gezeigt werden. Gilt nur, wenn Prioritätswarteschlange an ist."
L["Size of the queue icons in pixels. Only applies when Priority queue is on."] = "Größe der Warteschlangensymbole in Pixeln. Gilt nur, wenn Prioritätswarteschlange an ist."
L["Shows the name of the suggested spell under the main icon."] = "Zeigt den Namen des vorgeschlagenen Zaubers unter dem Hauptsymbol."
L["Shows a short reason under the spell name: why this spell is suggested now, or why the rotation is paused."] = "Zeigt einen kurzen Grund unter dem Zaubernamen: warum dieser Zauber jetzt vorgeschlagen wird oder warum die Rotation pausiert."
L["Hides the spell name, the reason text and the DPS strip in one go (in the classic layout also the queue), whatever their own toggles say. Same as /lazygcore hidename."] = "Blendet Zaubername, Begründungstext und DPS-Leiste auf einmal aus (im klassischen Layout auch die Warteschlange), egal was ihre eigenen Schalter sagen. Wie /lazygcore hidename."
L["Shows a health bar for your target above the main icon."] = "Zeigt über dem Hauptsymbol einen Gesundheitsbalken für dein Ziel."
L["Shows the warning line above the icon: buff reminders, a suggested spell missing from your action bars, a lower rank on your bars, a paused rotation. Off hides all of them."] = "Zeigt die Warnzeile über dem Symbol: Buff-Erinnerungen, ein vorgeschlagener Zauber, der auf deinen Aktionsleisten fehlt, ein niedrigerer Rang auf deinen Leisten, eine pausierte Rotation. Aus blendet all das aus."
L["Out of combat, the warning line names a missing buff ('Recommended: ...') or one about to run out, with its time left. Only applies when Warning line is on."] = "Außerhalb des Kampfes nennt die Warnzeile einen fehlenden Buff ('Empfohlen: ...') oder einen, der bald ausläuft, mit Restzeit. Gilt nur, wenn Warnzeile an ist."
L["Out of combat, the warning line lists up to three missing buffs ('Missing: ...') instead of naming only one. Only applies when Warning line is on."] = "Außerhalb des Kampfes listet die Warnzeile bis zu drei fehlende Buffs auf ('Fehlt: ...'), statt nur einen zu nennen. Gilt nur, wenn Warnzeile an ist."
L["Shows a row of small icons under the display with your important buffs and your damage over time spells on the target, with their time left."] = "Zeigt unter der Anzeige eine Reihe kleiner Symbole mit deinen wichtigen Buffs und deinen Schaden-über-Zeit-Zaubern auf dem Ziel, samt Restzeit."
L["Puts your active procs (Clearcasting, Shadow Trance, ...) first in the buff tracker. Only applies when Buff tracker is on."] = "Stellt deine aktiven Procs (Freizaubern, Schattentrance, ...) im Buff-Tracker an den Anfang. Gilt nur, wenn Buff-Tracker an ist."
L["Fades the display while there is nothing to suggest. How far is set by Idle Transparency."] = "Blendet die Anzeige ab, solange es nichts vorzuschlagen gibt. Wie stark, legt Leerlauf-Transparenz fest."
L["Shows your melee swing (Hunters: Auto Shot) on the ring around the main icon; it pulses when the next swing is ready. Only applies when Show outline is on."] = "Zeigt deinen Nahkampfschwung (Jäger: Automatischer Schuss) auf dem Ring um das Hauptsymbol; er pulsiert, wenn der nächste Schwung bereit ist. Gilt nur, wenn Umrandung anzeigen an ist."
L["How visible the display stays while idle, as a share of Overall Transparency (0.3 = 30%). Only applies when Fade when idle is on."] = "Wie sichtbar die Anzeige im Leerlauf bleibt, als Anteil der Gesamttransparenz (0.3 = 30%). Gilt nur, wenn Im Leerlauf ausblenden an ist."
L["Makes the action bar button of the suggested spell glow, so you find it at a glance."] = "Lässt den Aktionsleisten-Button des vorgeschlagenen Zaubers leuchten, damit du ihn auf einen Blick findest."
L["Look of that glow: LazyGCore glow (soft breathing glow), Marching ants, or Blizzard's own proc glow. Only applies when Glow the suggested spell is on."] = "Aussehen dieses Leuchtens: LazyGCore-Leuchten (sanftes, atmendes Leuchten), Laufende Ameisen oder Blizzards eigenes Proc-Leuchten. Gilt nur, wenn Vorgeschlagenen Zauber leuchten lassen an ist."
L["Color of that glow. Auto (Match Spec) uses your theme color. Only applies when Glow the suggested spell is on."] = "Farbe dieses Leuchtens. Auto (Spezialisierung) nutzt deine Designfarbe. Gilt nur, wenn Vorgeschlagenen Zauber leuchten lassen an ist."
L["When the suggested spell is not on your action bars, the spellbook button and the spell inside the spellbook glow, so you can drag it to a bar."] = "Ist der vorgeschlagene Zauber nicht auf deinen Aktionsleisten, leuchten der Zauberbuch-Button und der Zauber im Zauberbuch, damit du ihn auf eine Leiste ziehen kannst."
L["When a bar button holds a lower rank of the suggested spell, its glow turns orange and the warning line says which rank to put there."] = "Liegt auf einem Leisten-Button ein niedrigerer Rang des vorgeschlagenen Zaubers, wird sein Leuchten orange und die Warnzeile sagt, welcher Rang dorthin gehört."
L["Makes the action bar buttons of your spec's major cooldowns glow whenever they are ready, separately from the glow on the suggested spell."] = "Lässt die Aktionsleisten-Buttons der großen Abklingzeiten deiner Spezialisierung leuchten, sobald sie bereit sind, unabhängig vom Leuchten des vorgeschlagenen Zaubers."
L["Color of the cooldown glow (default green). Only applies when Enable Cooldown Glow is on."] = "Farbe des Abklingzeit-Leuchtens (Standard grün). Gilt nur, wenn Abklingzeit-Leuchten aktivieren an ist."
L["Adds swing bars inside the main icon: main hand (gold), off hand (blue) and ranged (green, GO when ready)."] = "Fügt Schwungleisten im Hauptsymbol hinzu: Waffenhand (gold), Schildhand (blau) und Fernkampf (grün, LOS wenn bereit)."
L["Starts or stops a test swing so you can see the swing timer without fighting."] = "Startet oder stoppt einen Testschwung, damit du den Swing-Timer ohne Kampf sehen kannst."
L["Includes your major offensive cooldowns, racials and on-use trinkets in the suggestions (in combat, with a target)."] = "Bezieht deine großen offensiven Abklingzeiten, Volksfähigkeiten und Benutzen-Schmuckstücke in die Vorschläge ein (im Kampf, mit Ziel)."
L["Suggests defensive spells and escapes when you are in danger: low health, stunned or feared. Also needed for the heal-your-pet and mana gem suggestions."] = "Schlägt Defensivzauber und Fluchtfähigkeiten vor, wenn du in Gefahr bist: wenig Gesundheit, betäubt oder verängstigt. Wird auch für die Vorschläge zum Heilen des Begleiters und für Manaedelsteine gebraucht."
L["Out of combat, the main icon suggests missing self-buffs, poisons and weapon imbues, calling or reviving your pet, and healing up between pulls."] = "Außerhalb des Kampfes schlägt das Hauptsymbol fehlende Selbstbuffs, Gifte und Waffenverzauberungen vor, das Rufen oder Wiederbeleben deines Begleiters und das Heilen zwischen den Pulls."
L["Lets LazyGCore switch to your spec's AoE spells when at least AoE enemy threshold enemies are near."] = "Lässt LazyGCore zu den AoE-Zaubern deiner Spezialisierung wechseln, wenn mindestens so viele Gegner wie bei Gegneranzahl für Flächenschaden in der Nähe sind."
L["Allows AoE suggestions in battlegrounds and against players. Off by default, because every nearby player counts as an enemy. Only applies when Enable AoE suggestions is on."] = "Erlaubt AoE-Vorschläge auf Schlachtfeldern und gegen Spieler. Standardmäßig aus, weil jeder Spieler in der Nähe als Gegner zählt. Gilt nur, wenn AoE-Vorschläge aktivieren an ist."
L["How many enemies are needed for AoE suggestions (default 3). LazyGCore counts living enemies in combat within about 10 yards, or in range of your ranged AoE spell, from their nameplates, so enemy nameplates must be on."] = "Wie viele Gegner für AoE-Vorschläge nötig sind (Standard 3). LazyGCore zählt lebende Gegner im Kampf in etwa 10 Metern Umkreis oder in Reichweite deines Fernkampf-AoE-Zaubers anhand ihrer Namensplaketten, die Namensplaketten der Gegner müssen also an sein."
L["Keeps the current suggestion for 0.3 seconds when another spell would briefly take over, so the icon doesn't flicker. Defensives always switch at once."] = "Behält den aktuellen Vorschlag 0,3 Sekunden bei, wenn kurz ein anderer Zauber übernehmen würde, damit das Symbol nicht flackert. Defensive wechseln immer sofort."
L["Suggests your race's abilities, such as Berserking or Stoneform, along with your other spells."] = "Schlägt die Fähigkeiten deines Volkes, etwa Berserker oder Steingestalt, zusammen mit deinen anderen Zaubern vor."
L["Shows ready on-use trinkets in the cooldown slot, and your PvP trinket when you are stunned or feared (with Suggest defensives on)."] = "Zeigt bereite Benutzen-Schmuckstücke im Abklingzeit-Platz und dein PvP-Schmuckstück, wenn du betäubt oder verängstigt bist (mit Defensivfähigkeiten vorschlagen an)."
L["Healers: never suggest damage spells, not even solo."] = "Heiler: nie Schadenszauber vorschlagen, auch nicht solo."
L["Healers in a group: suggest damage spells while nobody needs healing. Solo, healers always get damage suggestions."] = "Heiler in einer Gruppe: Schadenszauber vorschlagen, solange niemand Heilung braucht. Solo bekommen Heiler immer Schadensvorschläge."
L["Healers: heal suggestions are for the friendly player under your mouse when there is one. Changes the suggestion target only - it never targets anything."] = "Heiler: Heilvorschläge gelten dem freundlichen Spieler unter deiner Maus, falls es einen gibt. Ändert nur das Ziel des Vorschlags - es wird nie etwas anvisiert."
L["Shows a KICK! box to the left of the icon (left of the spell history when it shows) when your enemy target casts something you can interrupt and your interrupt is ready."] = "Zeigt einen KICK!-Kasten links neben dem Symbol (links neben dem Zauberverlauf, wenn er angezeigt wird), wenn dein feindliches Ziel etwas Unterbrechbares wirkt und deine Unterbrechung bereit ist."
L["Shows a DEFENSIVE! box in combat when your health drops below Defensive Threshold and a defensive spell is ready."] = "Zeigt im Kampf einen DEFENSIV!-Kasten, wenn deine Gesundheit unter die Defensive Schwelle fällt und ein Defensivzauber bereit ist."
L["Your health % below which the DEFENSIVE! box appears (default 35%). Only applies when Defensive Alerts is on."] = "Gesundheit in %, unter der der DEFENSIV!-Kasten erscheint (Standard 35%). Gilt nur, wenn Defensive Warnungen an ist."
L["Out of combat, shows a PURGE box when your enemy target has a magic buff and your purge or dispel is ready."] = "Zeigt außerhalb des Kampfes einen REINIGEN-Kasten, wenn dein feindliches Ziel einen magischen Buff hat und dein Reinigen- oder Bannzauber bereit ist."
L["Shows EXECUTE! on the main icon while your enemy target is below Execute threshold. Only if you know Execute, Hammer of Wrath or Shadow Word: Death."] = "Zeigt HINRICHTEN! auf dem Hauptsymbol, solange dein feindliches Ziel unter dem Hinrichtungs-Schwellenwert ist. Nur wenn du Hinrichten, Hammer des Zorns oder Schattenwort: Tod kennst."
L["Target health % below which EXECUTE! shows (default 20%). Only applies when Execute phase is on."] = "Zielgesundheit in %, unter der HINRICHTEN! erscheint (Standard 20%). Gilt nur, wenn Hinrichtungsphase an ist."
L["In combat, warns above the icon when your mana, rage or energy (and your pet's health) drops below the thresholds below."] = "Warnt im Kampf über dem Symbol, wenn dein Mana, deine Wut oder Energie (und die Gesundheit deines Begleiters) unter die Schwellen unten fällt."
L["Mana % below which the low mana warning shows (default 20%). Only applies when Low resource warnings is on."] = "Mana in %, unter dem die Warnung bei wenig Mana erscheint (Standard 20%). Gilt nur, wenn Warnungen bei niedrigen Ressourcen an ist."
L["Rage below which the low rage warning shows (default 20). Only applies when Low resource warnings is on."] = "Wut, unter der die Warnung bei wenig Wut erscheint (Standard 20). Gilt nur, wenn Warnungen bei niedrigen Ressourcen an ist."
L["Energy below which the low energy warning shows (default 30). Only applies when Low resource warnings is on."] = "Energie, unter der die Warnung bei wenig Energie erscheint (Standard 30). Gilt nur, wenn Warnungen bei niedrigen Ressourcen an ist."
L["Pet health % below which the pet warning shows (default 30%). Only applies when Low resource warnings is on."] = "Begleitergesundheit in %, unter der die Begleiterwarnung erscheint (Standard 30%). Gilt nur, wenn Warnungen bei niedrigen Ressourcen an ist."
L["Shows the KICK! box for 3 seconds so you can see where it appears."] = "Zeigt den KICK!-Kasten 3 Sekunden lang, damit du siehst, wo er erscheint."
L["Shows the DEFENSIVE! box for 3 seconds so you can see where it appears."] = "Zeigt den DEFENSIV!-Kasten 3 Sekunden lang, damit du siehst, wo er erscheint."
L["Shows the PURGE box for 3 seconds so you can see where it appears."] = "Zeigt den REINIGEN-Kasten 3 Sekunden lang, damit du siehst, wo er erscheint."
L["Plays the alert sound when a KICK!, DEFENSIVE! or PURGE box appears, on low resource warnings and when a buff goes missing. Off by default."] = "Spielt den Warnton, wenn ein KICK!-, DEFENSIV!- oder REINIGEN-Kasten erscheint, bei Warnungen zu niedrigen Ressourcen und wenn ein Buff fehlt. Standardmäßig aus."
L["Silences every sound LazyGCore plays, including the proc and weapon buff sounds."] = "Schaltet jeden Ton von LazyGCore stumm, auch die Proc- und Waffenbuff-Töne."
L["Plays a sound when a proc becomes the suggestion. Works even with Sound alerts off."] = "Spielt einen Ton, wenn ein Proc zum Vorschlag wird. Funktioniert auch bei ausgeschalteten Ton-Warnungen."
L["Which sound the alerts play. Only applies when Sound alerts is on."] = "Welchen Ton die Warnungen spielen. Gilt nur, wenn Ton-Warnungen an ist."
L["Plays the chosen alert sound once."] = "Spielt den gewählten Warnton einmal ab."
L["How often suggestions are recalculated in combat. Faster reacts sooner but uses more CPU; casts, cooldowns and target changes refresh at once anyway. Default 20 per second."] = "Wie oft die Vorschläge im Kampf neu berechnet werden. Schneller reagiert früher, braucht aber mehr CPU; Zauber, Abklingzeiten und Zielwechsel aktualisieren ohnehin sofort. Standard 20 pro Sekunde."
L["How often suggestions are recalculated out of combat. Slower saves CPU between fights; it is never faster than Update rate. Default 2 per second."] = "Wie oft die Vorschläge außerhalb des Kampfes neu berechnet werden. Langsamer spart zwischen den Kämpfen CPU; nie schneller als die Aktualisierungsrate. Standard 2 pro Sekunde."
L["Prints extra diagnostic messages to chat. Errors are reported either way; leave this off unless you are tracking down a problem."] = "Gibt zusätzliche Diagnosemeldungen im Chat aus. Fehler werden so oder so gemeldet; lass das aus, außer du suchst ein Problem."
L["Prints LazyGCore's status to chat: version, class, spec, engine and the settings that affect suggestions. Useful for bug reports."] = "Gibt LazyGCores Status im Chat aus: Version, Klasse, Spezialisierung, Engine und die Einstellungen, die die Vorschläge beeinflussen. Nützlich für Fehlerberichte."
L["Prints which spells of your class rotation you know and which are still missing from your spellbook."] = "Gibt aus, welche Zauber deiner Klassenrotation du kennst und welche noch in deinem Zauberbuch fehlen."
L["Turns on the game's Lua error pop-ups, to see errors from any addon."] = "Schaltet die Lua-Fehlerfenster des Spiels ein, um Fehler aller Addons zu sehen."
L["Turns off the game's Lua error pop-ups."] = "Schaltet die Lua-Fehlerfenster des Spiels aus."
L["Prints the buffs and procs the buff tracker watches for your spec to chat."] = "Gibt im Chat aus, welche Buffs und Procs der Buff-Tracker für deine Spezialisierung beobachtet."
L["Prints what LazyGCore suggests right now, and why, to chat."] = "Gibt im Chat aus, was LazyGCore gerade vorschlägt und warum."
L["Prints the details behind the DPS/HPS numbers to chat."] = "Gibt im Chat die Details hinter den DPS/HPS-Werten aus."
L["Resets every account-wide LazyGCore setting to its default after you confirm. Your saved profiles and this character's spec, talent build and custom rotations are kept."] = "Setzt nach deiner Bestätigung jede accountweite LazyGCore-Einstellung auf den Standard zurück. Deine gespeicherten Profile sowie Spezialisierung, Talentbuild und eigene Rotationen dieses Charakters bleiben erhalten."
L["Makes the action bar buttons holding this spell glow for 5 seconds, to check that LazyGCore finds it. Empty box: the current suggestion."] = "Lässt die Aktionsleisten-Buttons mit diesem Zauber 5 Sekunden lang leuchten, um zu prüfen, ob LazyGCore ihn findet. Leeres Feld: der aktuelle Vorschlag."
L["Removes the test glow."] = "Entfernt das Test-Leuchten."
L["Spell to test: type its name, or leave the box empty for the current suggestion. Enter or Test makes its action bar buttons glow."] = "Zu testender Zauber: Namen eingeben oder das Feld für den aktuellen Vorschlag leer lassen. Eingabe oder Testen lässt seine Aktionsleisten-Tasten leuchten."
L["Language of LazyGCore's text. Auto uses your game client's language. Applies after a UI reload."] = "Sprache von LazyGCores Texten. Auto nutzt die Sprache deines Spielclients. Wirkt nach einem UI-Neuladen."
L["Reloads the interface now, so a new language takes effect."] = "Lädt die Oberfläche jetzt neu, damit eine neue Sprache wirksam wird."
L["Sets every option on this page back to its default."] = "Setzt jede Option auf dieser Seite auf den Standard zurück."
L["Switches between your custom rotation and LazyGCore's default priority for this spec."] = "Wechselt zwischen deiner eigenen Rotation und LazyGCores Standardpriorität für diese Spezialisierung."
L["When the spell is suggested. Conditions marked * are estimates in combat, because Forever hides health, mana and most auras there."] = "Wann der Zauber vorgeschlagen wird. Mit * markierte Bedingungen sind im Kampf Schätzungen, weil Forever dort Gesundheit, Mana und die meisten Auren verbirgt."
L["Adds the spell typed in the box to the end of your list, with the condition chosen beside it."] = "Fügt den im Feld eingegebenen Zauber am Ende deiner Liste hinzu, mit der daneben gewählten Bedingung."
L["Gives the entry selected in the list the spell, condition and values chosen here. A default rule becomes your own rule."] = "Gibt dem in der Liste ausgewählten Eintrag den hier gewählten Zauber, die Bedingung und die Werte. Eine Standardregel wird zu deiner eigenen Regel."
L["Fills the list with LazyGCore's default priority for your current spec, so you can edit it."] = "Füllt die Liste mit LazyGCores Standardpriorität für deine aktuelle Spezialisierung, damit du sie bearbeiten kannst."
L["Saves the list as this spec's saved rotation."] = "Speichert die Liste als gespeicherte Rotation dieser Spezialisierung."
L["Loads this spec's saved rotation into the list."] = "Lädt die gespeicherte Rotation dieser Spezialisierung in die Liste."
L["No saved rotation for this spec yet: use Save Custom first."] = "Noch keine gespeicherte Rotation für diese Spezialisierung: nutze zuerst Eigene speichern."
L["Removes every spell from the list, after you confirm."] = "Entfernt nach deiner Bestätigung alle Zauber aus der Liste."
L["Saves the list under the name typed in the box, so you can keep several rotations."] = "Speichert die Liste unter dem im Feld eingegebenen Namen, damit du mehrere Rotationen behalten kannst."
L["Your named rotations, with their spec and number of spells. Pick one, then Load or Delete it."] = "Deine benannten Rotationen, mit Spezialisierung und Anzahl der Zauber. Wähle eine aus und dann Laden oder Löschen."
L["Loads the named rotation picked beside it into the list."] = "Lädt die daneben gewählte benannte Rotation in die Liste."
L["Deletes the named rotation picked beside it, after you confirm."] = "Löscht nach deiner Bestätigung die daneben gewählte benannte Rotation."
L["Gives the named rotation picked below the name typed in the box."] = "Gibt der unten gewählten benannten Rotation den im Feld eingegebenen Namen."
L["LazyGCore suggests from your list above instead of its default priority for this spec. Defensives and the cooldown slot still work as usual."] = "LazyGCore schlägt aus deiner Liste oben vor statt aus seiner Standardpriorität für diese Spezialisierung. Defensive und der Abklingzeit-Platz funktionieren wie gewohnt."
L["When nothing in your list is ready, the default priority fills in. Only applies when Use Custom Rotation is on."] = "Ist nichts aus deiner Liste bereit, springt die Standardpriorität ein. Gilt nur, wenn Benutzerdefinierte Rotation verwenden an ist."
L["Never suggest the spell typed in the box (also not in the cooldown slot or the cooldown glow)."] = "Den im Feld eingegebenen Zauber nie vorschlagen (auch nicht im Abklingzeit-Platz oder beim Abklingzeit-Leuchten)."
L["Lets the spell in the box, or the one selected in the list, be suggested again."] = "Lässt den Zauber im Feld oder den in der Liste ausgewählten wieder vorschlagen."
L["Prints every excluded spell to chat."] = "Gibt jeden ausgeschlossenen Zauber im Chat aus."
L["Removes every exclusion, after you confirm."] = "Entfernt nach deiner Bestätigung alle Ausschlüsse."
L["Turns LazyGCore off while you are in a battleground: no display, suggestions or glows there."] = "Schaltet LazyGCore auf Schlachtfeldern ab: dort keine Anzeige, keine Vorschläge und kein Leuchten."
L["Turns LazyGCore off while you are in an arena: no display, suggestions or glows there."] = "Schaltet LazyGCore in Arenen ab: dort keine Anzeige, keine Vorschläge und kein Leuchten."
L["Stops spell suggestions everywhere, not only in battlegrounds or arenas, but keeps the display with the DPS strip and swing timer."] = "Stoppt Zaubervorschläge überall, nicht nur auf Schlachtfeldern oder in Arenen, behält aber die Anzeige mit DPS-Leiste und Swing-Timer."
L["Shows an estimated parse percentile in the Stats window, based on this spec's benchmark numbers."] = "Zeigt im Statistikfenster ein geschätztes Parse-Perzentil, basierend auf den Vergleichswerten dieser Spezialisierung."
L["Keeps your last fight's numbers on the DPS strip after combat ends instead of hiding it. Only applies when Show DPS/HPS is on."] = "Behält die Werte deines letzten Kampfes nach Kampfende auf der DPS-Leiste, statt sie auszublenden. Gilt nur, wenn DPS/HPS anzeigen an ist."
L["Shows how your DPS compares to your personal best: the difference in DPS on the DPS strip, +/- % in the Stats window."] = "Zeigt deinen DPS im Vergleich zu deinem persönlichen Rekord: den DPS-Unterschied auf der DPS-Leiste, +/- % im Statistikfenster."
L["Shows your rotation efficiency score on the DPS strip and in the Stats window."] = "Zeigt deine Rotationseffizienz auf der DPS-Leiste und im Statistikfenster."
L["When the DPS numbers start over. Each combat: every fight. Boss only: fights add up until a boss fight starts. Manual: only when you press Reset Now."] = "Wann die DPS-Werte neu beginnen. Jeden Kampf: bei jedem Kampf. Nur Boss: Kämpfe summieren sich, bis ein Bosskampf beginnt. Manuell: nur wenn du Jetzt zurücksetzen drückst."
L["Clears the DPS numbers now (in Manual mode also Blizzard's damage meter)."] = "Löscht die DPS-Werte sofort (im Modus Manuell auch Blizzards Schadensmesser)."
L["Prints your last 10 fights to chat."] = "Gibt deine letzten 10 Kämpfe im Chat aus."
L["Dark box behind the DPS strip. 0 (default) = no box. Only applies when Show DPS/HPS is on."] = "Dunkler Kasten hinter der DPS-Leiste. 0 (Standard) = kein Kasten. Gilt nur, wenn DPS/HPS anzeigen an ist."
L["Opacity of the floating Stats window."] = "Deckkraft des schwebenden Statistikfensters."
L["Adds a player's gear score and item level to their tooltip when you hover them."] = "Fügt dem Tooltip eines Spielers seinen GearScore und seine Gegenstandsstufe hinzu, wenn du mit der Maus über ihn fährst."
L["Rescans your gear and buffs and updates the boxes above."] = "Liest deine Ausrüstung und Buffs neu ein und aktualisiert die Felder oben."
L["Saves your current settings as a profile with the name typed in the box (replaces a profile of that name) and makes it active."] = "Speichert deine aktuellen Einstellungen als Profil mit dem im Feld eingegebenen Namen (ersetzt ein gleichnamiges Profil) und macht es aktiv."
L["Loads the profile selected in the list. Double-clicking a profile does the same."] = "Lädt das in der Liste ausgewählte Profil. Ein Doppelklick auf ein Profil macht dasselbe."
L["Deletes the selected profile, after you confirm. The Default profile can't be deleted."] = "Löscht nach deiner Bestätigung das ausgewählte Profil. Das Standardprofil kann nicht gelöscht werden."
L["Gives the selected profile the name typed in the box."] = "Gibt dem ausgewählten Profil den im Feld eingegebenen Namen."
L["Copies the selected profile (or the active one) to a new profile with the name typed in the box."] = "Kopiert das ausgewählte (oder das aktive) Profil in ein neues Profil mit dem im Feld eingegebenen Namen."
L["When your detected spec changes, loads the profile you assigned to that spec with Use for this spec."] = "Wenn sich deine erkannte Spezialisierung ändert, wird das Profil geladen, das du ihr mit Für diese Spez. zugewiesen hast."
L["Assigns the selected profile (or the active one) to your current spec."] = "Weist das ausgewählte (oder das aktive) Profil deiner aktuellen Spezialisierung zu."
L["Removes the profile assigned to your current spec."] = "Entfernt das deiner aktuellen Spezialisierung zugewiesene Profil."
L["Puts the selected profile (or the active one) in the box as a text string you can copy and share. The active profile exports your current settings, including changes you have not saved."] = "Schreibt das ausgewählte (oder das aktive) Profil als Text ins Feld, den du kopieren und teilen kannst. Beim aktiven Profil werden deine aktuellen Einstellungen exportiert, auch nicht gespeicherte Änderungen."
L["Saves the profile string pasted in the box as a profile, named by the name box or by the string itself."] = "Speichert den ins Feld eingefügten Profiltext als Profil, benannt nach dem Namensfeld oder nach dem Text selbst."
L["While the talent frame is open, a green NEXT glow marks the next talent of your build, and the right spec tab and the Apply button are pointed out. Also prints a chat note when a point is free."] = "Bei offenem Talentfenster markiert ein grünes WEITER-Leuchten das nächste Talent deines Builds, und der richtige Spezialisierungsreiter und der Übernehmen-Button werden hervorgehoben. Gibt außerdem einen Chathinweis aus, wenn ein Punkt frei ist."
L["Makes the talent button on the micro menu glow while you have an unspent point for your build. Only applies when Glow the next talent in the talent frame is on."] = "Lässt den Talent-Button im Mikromenü leuchten, solange du einen unverteilten Punkt für deinen Build hast. Gilt nur, wenn Nächstes Talent im Talentfenster leuchten lassen an ist."
L["Opens the Next Talent popup with the next talent of your build."] = "Öffnet das Popup Nächstes Talent mit dem nächsten Talent deines Builds."
L["Opens the build browser to pick another talent build for your spec."] = "Öffnet die Build-Auswahl, um einen anderen Talent-Build für deine Spezialisierung zu wählen."
L["Shows this spec's recommended talent build below."] = "Zeigt unten den empfohlenen Talent-Build dieser Spezialisierung."
L["Picks this spec's leveling build."] = "Wählt den Leveln-Build dieser Spezialisierung."
L["Picks this spec's PvE build (dungeons and raids)."] = "Wählt den PvE-Build dieser Spezialisierung (Dungeons und Schlachtzüge)."
L["Picks this spec's PvP build."] = "Wählt den PvP-Build dieser Spezialisierung."
L["Cycles this spec's build type: Leveling, PvE, PvP."] = "Wechselt den Build-Typ dieser Spezialisierung: Leveln, PvE, PvP."
L["Picks which of this spec's talent builds the guide shows and follows."] = "Wählt, welchen Talentbuild dieser Spezialisierung der Talentratgeber zeigt und verfolgt."
L["Re-reads your talents and stops following a build started with Start Build."] = "Liest deine Talente neu ein und folgt keinem mit Build starten begonnenen Build mehr."
L["Opens the game's talent frame."] = "Öffnet das Talentfenster des Spiels."
L["Opens the game's macro window (/macro), where you drag the macros you created to your bars."] = "Öffnet das Makrofenster des Spiels (/macro), wo du die erstellten Makros auf deine Leisten ziehst."
L["Updates every macro you already created from this page to its latest version."] = "Aktualisiert jedes Makro, das du auf dieser Seite schon erstellt hast, auf die neueste Version."
L["Visibility"] = "Sichtbarkeit"
L["Suggestions"] = "Vorschläge"
L["Troubleshooting"] = "Fehlerbehebung"
L["Hide name, reason and DPS strip"] = "Name, Grund und DPS-Leiste ausblenden"
L["Buff reminder text"] = "Buff-Erinnerungstext"
L["List all missing buffs"] = "Alle fehlenden Buffs auflisten"
L["Suggest buffs & pets"] = "Buffs & Begleiter vorschlagen"
L["Glow the suggested spell"] = "Vorgeschlagenen Zauber leuchten lassen"
L["Saved rotations"] = "Gespeicherte Rotationen"
L["Balance: remind you to be in Moonkin Form out of combat, and suggest shifting back into it after a caster-form heal in combat"] = "Gleichgewicht: erinnert dich außerhalb des Kampfes an die Moonkingestalt und schlägt nach einer Heilung in Zaubergestalt im Kampf vor, wieder hineinzuwechseln"
L["Feral, in groups only (solo, LazyGCore picks the form itself). Bear always suggests Bear Form, Cat never does. Auto: Bear when you are in Bear Form, the group made you its tank, you run a Bear build or your last shift was into Bear; otherwise Cat"] = "Wilder Kampf, nur in Gruppen (solo wählt LazyGCore die Gestalt selbst). Bär schlägt immer Bärengestalt vor, Katze nie. Auto: Bär, wenn du in Bärengestalt bist, die Gruppe dich zum Tank gemacht hat, du einen Bären-Build spielst oder dein letzter Wechsel in Bärengestalt war; sonst Katze"
L["In Bear Form, in combat, suggest Frenzied Regeneration below this health %. Needs Suggest defensives on (Combat page)"] = "In Bärengestalt im Kampf Rasende Regeneration unter diesem Gesundheitswert in % vorschlagen. Braucht Defensivfähigkeiten vorschlagen an (Seite 'Kampf')"
L["Suggest Hunter's Mark on elites, group targets, players and mobs above 60% health. Survival skips normal solo mobs it is about to melee, unless it has Expose Prey (which only procs on Marked targets)"] = "Mal des Jägers auf Elites, Gruppenziele, Spieler und Mobs über 60% Gesundheit vorschlagen. Überleben lässt normale Solo-Mobs aus, die es gleich im Nahkampf angreift, außer mit Beute aufspüren (das nur bei markierten Zielen auslöst)"
L["Out of combat, remind you to call your pet, revive it if it died, or feed it when it is not happy. Skipped if you have the Lone Wolf talent"] = "Außerhalb des Kampfes daran erinnern, deinen Begleiter zu rufen, ihn wiederzubeleben, falls er tot ist, oder ihn zu füttern, wenn er nicht zufrieden ist. Entfällt mit dem Talent Einsamer Wolf"
L["Out of combat, remind you to put up your combat aspect: Aspect of the Hawk (Monkey before level 10); Survival uses Monkey until it learns Aspect of the Beast. Waits while Cheetah, Pack or Wild is on, and in combat warns when Cheetah or Pack is still on"] = "Außerhalb des Kampfes an deinen Kampfaspekt erinnern: Aspekt des Falken (vor Stufe 10 Aspekt des Affen); Überleben nutzt den Affen, bis es Aspekt des Wildtiers lernt. Wartet, solange Gepard, Rudel oder Wildnis aktiv ist, und warnt im Kampf, wenn Gepard oder Rudel noch aktiv ist"
L["In combat, suggest Mend Pet when your pet drops below this % (out of combat it reminds you below 60%). Forever hides pet health in combat: LazyGCore estimates it from the damage and heals your pet takes. Needs Suggest defensives on (Combat page)"] = "Im Kampf Tier heilen vorschlagen, wenn dein Begleiter unter diesen Wert in % fällt (außerhalb des Kampfes erinnert es unter 60%). Forever verbirgt die Begleitergesundheit im Kampf: LazyGCore schätzt sie anhand des Schadens und der Heilung, die dein Begleiter erhält. Braucht Defensivfähigkeiten vorschlagen an (Seite 'Kampf')"
L["Arcane: Arcane Blast stacks to build on elites, bosses, groups and players before Arcane Wrath and Arcane Missiles. Each stack adds 15% of your Intellect as spell damage for 15 seconds from the first Blast, but makes the next Blast cost more (trash always gets one Blast)"] = "Arkan: Arkanschlag-Stapel, die bei Elites, Bossen, in Gruppen und gegen Spieler vor Arkaner Zorn und Arkanen Geschossen aufgebaut werden. Jeder Stapel gibt 15% deiner Intelligenz als Zauberschaden für 15 Sekunden ab dem ersten Schlag, verteuert aber den nächsten Schlag (Trash bekommt immer einen Schlag)"
L["Fire with 3 points in Improved Scorch: keep this many Fire Vulnerability stacks up with Scorch on bosses, skull-marked targets and elites (solo or in a raid; never on players)"] = "Feuer mit 3 Punkten in Verbessertes Versengen: so viele Stapel Feuerverwundbarkeit mit Versengen aufrechterhalten, auf Bossen, mit Totenkopf markierten Zielen und Elites (solo oder im Schlachtzug; nie auf Spielern)"
L["Suggest Evocation when you run low on mana: out of combat below the Evocation Threshold, in combat once you can't afford your filler spell"] = "Hervorrufung vorschlagen, wenn dein Mana knapp wird: außerhalb des Kampfes unter der Hervorrufung-Schwelle, im Kampf sobald du dir deinen Füllzauber nicht mehr leisten kannst"
L["In combat, suggest a mana gem when you run low on mana, before Evocation (needs Suggest defensives and Suggest cooldowns on, Combat page). Out of combat, remind you to conjure one when your bags have none"] = "Im Kampf einen Manaedelstein vor Hervorrufung vorschlagen, wenn dein Mana knapp wird (braucht Defensivfähigkeiten vorschlagen und Abklingzeiten vorschlagen an, Seite 'Kampf'). Außerhalb des Kampfes daran erinnern, einen herzustellen, wenn keiner in deinen Taschen ist"
L["Suggest Evocation when mana is below this %. Out of combat only: Forever hides your mana in combat, so there Evocation is suggested once you can't afford your filler spell"] = "Hervorrufung vorschlagen, wenn Mana unter diesem Wert in % ist. Nur außerhalb des Kampfes: Forever verbirgt dein Mana im Kampf, dort wird Hervorrufung vorgeschlagen, sobald du dir deinen Füllzauber nicht mehr leisten kannst"
L["Suggest Consecration in melee range when mana allows, mostly on packs and elites. Applies to every spec (Holy only when solo)"] = "Weihe in Nahkampfreichweite vorschlagen, wenn das Mana reicht, vor allem bei Gruppen von Gegnern und Elites. Gilt für jede Spezialisierung (Heilig nur solo)"
L["Protection: on keeps Holy Shield up whenever you are in melee. Off: only against elites or when your health is below 50%"] = "Schutz: an hält Heiliger Schild aufrecht, solange du im Nahkampf bist. Aus: nur gegen Elites oder wenn deine Gesundheit unter 50% ist"
L["Out of combat, remind you to put your blessing on yourself when it is missing or has under 1 minute left. Holy in a group: also Blessing of Kings on the ally you heal"] = "Außerhalb des Kampfes daran erinnern, deinen Segen auf dich zu legen, wenn er fehlt oder weniger als 1 Minute übrig hat. Heilig in einer Gruppe: auch Segen der Könige auf den Verbündeten, den du heilst"
L["The blessing the reminder keeps on you (needs Blessing Reminder on). Auto: Wisdom for Holy, Kings for Protection, Might otherwise. Might is used until the chosen one is learned"] = "Der Segen, den die Erinnerung auf dir hält (braucht Segen-Erinnerung an). Auto: Weisheit für Heilig, Könige für Schutz, sonst Macht. Bis der gewählte gelernt ist, wird Macht genutzt"
L["Auto: the new Shadow Word: Pain lands right as the old one ends (recasting early throws away its remaining ticks). Or refresh when this many seconds remain. Applies to every spec while it deals damage"] = "Auto: Schattenwort: Schmerz landet genau, wenn der alte ausläuft (früh neu wirken wirft seine restlichen Ticks weg). Oder auffrischen, wenn noch so viele Sekunden übrig sind. Gilt für jede Spezialisierung, solange sie Schaden macht"
L["Only suggest Shadow Word: Death while your own health is above this % (it hurts you if the target survives)"] = "Schattenwort: Tod nur vorschlagen, solange deine eigene Gesundheit über diesem Wert in % ist (es verletzt dich, wenn das Ziel überlebt)"
L["Never suggest Fade. When off, Fade is suggested in a group as soon as you pull threat"] = "Verblassen nie vorschlagen. Wenn aus, wird Verblassen in einer Gruppe vorgeschlagen, sobald du Bedrohung ziehst"
L["In combat, suggest Mind Blast every time it comes off cooldown. Off: the normal priority decides, and normal mobs often get your wand to save mana"] = "Im Kampf Gedankenschlag jedes Mal vorschlagen, wenn seine Abklingzeit vorbei ist. Aus: die normale Priorität entscheidet, und normale Mobs bekommen oft deinen Zauberstab, um Mana zu sparen"
L["Combo points to build before Eviscerate. Auto: 5 with talents (4 before), and 4 on normal mobs while questing (3 below level 20) so they die sooner. A target about to die gets Eviscerate from 2 points"] = "Kombopunkte, die vor Ausweiden aufgebaut werden. Auto: 5 mit Talenten (vorher 4) und 4 bei normalen Mobs beim Questen (unter Stufe 20: 3), damit sie schneller sterben. Ein Ziel kurz vor dem Tod bekommt Ausweiden ab 2 Punkten"
L["Keep Slice and Dice up (from 2 combo points, 4 for Combat) on targets above 25% health. Leveling and Combat skip normal mobs while questing; Assassination and Subtlety skip players. Off: never suggest it"] = "Zerhäckseln (ab 2 Kombopunkten, Kampf ab 4) auf Zielen über 25% Gesundheit aufrechterhalten. Leveln und Kampf lassen normale Mobs beim Questen aus; Meucheln und Täuschung lassen Spieler aus. Aus: nie vorschlagen"
L["Auto: each spec's own choice (Assassination: Rupture on elites, Subtlety: on elites, groups and players, Combat and leveling: Eviscerate only). Rupture: Rupture first whenever it is missing on a target above 35% health. Eviscerate: never Rupture"] = "Auto: die Wahl der jeweiligen Spezialisierung (Meucheln: Blutung bei Elites, Täuschung: bei Elites, Gruppen und Spielern, Kampf und Leveln: nur Ausweiden). Blutung: zuerst Blutung, wenn sie auf einem Ziel über 35% Gesundheit fehlt. Ausweiden: nie Blutung"
L["Assassination and Combat: in a group, suggest Vanish against an elite (while you don't hold threat) so you can use a stealth opener again. Subtlety has its own Vanish rule"] = "Meucheln und Kampf: in einer Gruppe Verschwinden gegen Elitegegner vorschlagen (solange du keine Bedrohung hast), damit du erneut einen Eröffner aus der Verstohlenheit nutzen kannst. Täuschung hat eine eigene Verschwinden-Regel"
L["Suggest your damage and buff totems (Searing, Magma, Strength of Earth, water totems, totem sets), mostly on elites, groups and players; Magma Totem on packs. Off: only utility totems such as Stoneclaw, Grounding, Tremor and Mana Tide are still suggested"] = "Deine Schadens- und Buff-Totems vorschlagen (Totem der Verbrennung, Totem der glühenden Magma, Totem der Erdstärke, Wassertotems, Totem-Sets), vor allem bei Elites, Gruppen und Spielern; Totem der glühenden Magma bei Gruppen von Gegnern. Aus: nur noch Hilfstotems wie Totem der Steinklaue, Totem der Erdung, Totem des Erdstoßes und Totem der Manaflut werden vorgeschlagen"
L["Enhancement and Restoration, once you have Water Shield: remind you to refresh it out of combat when under 1 minute, and recast it in combat when it drops"] = "Verstärkung und Wiederherstellung, sobald du Wasserschild hast: erinnert dich, es außerhalb des Kampfes unter 1 Minute aufzufrischen, und schlägt im Kampf vor, es neu zu wirken, wenn es ausläuft"
L["Restoration: suggest Chain Heal when at least this many group members are below 80% health. In combat Forever hides group health: LazyGCore estimates it from the damage and heals they take"] = "Wiederherstellung: Kettenheilung vorschlagen, wenn mindestens so viele Gruppenmitglieder unter 80% Gesundheit sind. Im Kampf verbirgt Forever die Gruppengesundheit: LazyGCore schätzt sie anhand des Schadens und der Heilung, die sie erhalten"
L["Suggest Life Tap when you run low on mana and your health is above 50%. Between pulls it also reminds you below 60% mana when your health is above 75%"] = "Aderlass vorschlagen, wenn dein Mana knapp wird und deine Gesundheit über 50% ist. Zwischen den Pulls erinnert es dich auch unter 60% Mana, wenn deine Gesundheit über 75% ist"
L["Suggest Life Tap when mana is below this % (health above 50%). Forever hides your mana in combat, so there Life Tap is suggested once you can't afford Shadow Bolt. Between pulls a separate reminder appears below 60% mana"] = "Aderlass vorschlagen, wenn Mana unter diesem Wert in % ist (Gesundheit über 50%). Forever verbirgt dein Mana im Kampf, dort wird Aderlass vorgeschlagen, sobald du dir Schattenblitz nicht mehr leisten kannst. Zwischen den Pulls erscheint unter 60% Mana eine eigene Erinnerung"
L["Solo, in combat: suggest Health Funnel when your demon drops below this % and your own health is above 55%. Forever hides pet health in combat: LazyGCore estimates it from the damage and heals your demon takes. Needs Suggest defensives on (Combat page)"] = "Solo, im Kampf: Lebenslinie vorschlagen, wenn dein Dämon unter diesen Wert in % fällt und deine eigene Gesundheit über 55% ist. Forever verbirgt die Begleitergesundheit im Kampf: LazyGCore schätzt sie anhand des Schadens und der Heilung, die dein Dämon erhält. Braucht Defensivfähigkeiten vorschlagen an (Seite 'Kampf')"
L["Your one Curse per target. Auto: Curse of the Elements on elites and in groups (Curse of Weakness on elites before you learn it); on players Curse of Tongues for casters, Curse of Exhaustion or Weakness for the rest. A fixed curse goes on elites, group targets and players; None leaves the Curse to another Warlock (Banes still apply)"] = "Dein einer Fluch pro Ziel. Auto: Fluch der Elemente bei Elites und in Gruppen (Fluch der Schwäche bei Elites, bevor du ihn lernst); gegen Spieler Fluch der Sprachen bei Zauberern, Fluch der Erschöpfung oder der Schwäche beim Rest. Ein fester Fluch kommt auf Elites, Gruppenziele und Spieler; Keiner überlässt den Fluch einem anderen Hexenmeister (Omen gelten weiter)"
L["Destruction only. Also picks your weapon stone (Firestone with Incinerate, Spellstone with Shadow Bolt) and the demon you sacrifice (Sayaad or Imp). Auto: Incinerate if you have the Incinerate talent and 5 points in Shadow and Flame, otherwise Shadow Bolt"] = "Nur Zerstörung. Wählt auch deinen Waffenstein (Feuerstein mit Verbrennen, Zauberstein mit Schattenblitz) und den Dämon, den du opferst (Sayaad oder Wichtel). Auto: Verbrennen, wenn du das Talent Verbrennen und 5 Punkte in Schatten und Flamme hast, sonst Schattenblitz"
L["Protection: build Sunder Armor to this many stacks on elites and in dungeons and raids, and refresh it before it drops (normal mobs while questing get 2)"] = "Schutz: Rüstung zerreißen auf Elites und in Dungeons und Schlachtzügen bis zu so vielen Stapeln aufbauen und auffrischen, bevor es ausläuft (normale Mobs beim Questen bekommen 2)"
L["Use Heroic Strike when rage is above this (Auto = per spec: 30 leveling, 60 Arms/Fury, 45 Protection). In combat Rage is hidden: LazyGCore checks you could still afford a spell of that cost (30+: Mortal Strike / Bloodthirst, 25: Intimidating Shout / Whirlwind, 20: Cleave / Thunder Clap, 15 or less: Heroic Strike)"] = "Heldenhafter Stoß nutzen, wenn die Wut über diesem Wert liegt (Auto = je Spezialisierung: 30 Leveln, 60 Waffen/Furor, 45 Schutz). Im Kampf ist Wut verborgen: LazyGCore prüft, ob du dir noch einen Zauber dieser Kosten leisten könntest (30+: Tödlicher Stoß / Blutdurst, 25: Drohruf / Wirbelwind, 20: Spalten / Donnerknall, 15 oder weniger: Heldenhafter Stoß)"
L["Protection: on suggests Shield Block whenever you are tanking in melee. Off: only against elites or when your health is below 50%"] = "Schutz: an schlägt Schildblock vor, wann immer du im Nahkampf tankst. Aus: nur gegen Elites oder wenn deine Gesundheit unter 50% ist"
L["Suggest Battle Shout whenever it is missing (out of combat also when under 10 seconds remain)"] = "Schlachtruf vorschlagen, wann immer er fehlt (außerhalb des Kampfes auch, wenn weniger als 10 Sekunden übrig sind)"

-- sim pass: raid-only utility options
L["Faerie Fire in raids"] = "Feenfeuer in Schlachtzügen"
L["Balance: keep Faerie Fire's armor debuff on the boss in raids. It only helps physical attackers and costs you a GCD and mana, so leave it off unless your raid has no other armor debuff. Groups of 5 always get it"] = "Gleichgewicht: hält in Schlachtzügen den Rüstungs-Debuff von Feenfeuer auf dem Boss. Er hilft nur körperlichen Angreifern und kostet dich eine globale Abklingzeit und Mana – lass ihn aus, außer dein Schlachtzug hat keinen anderen Rüstungs-Debuff. In 5er-Gruppen wird er immer vorgeschlagen"
L["Vampiric Embrace in raids"] = "Vampirumarmung in Schlachtzügen"
L["Shadow: keep Vampiric Embrace on the boss in raids so your Shadow damage heals your party. It does no damage and costs a GCD every 30 seconds. In groups of 5 and in battlegrounds it is always suggested; solo only while your health is below 60%"] = "Schatten: hält in Schlachtzügen Vampirumarmung auf dem Boss, damit dein Schattenschaden deine Gruppe heilt. Sie macht keinen Schaden und kostet alle 30 Sekunden eine globale Abklingzeit. In 5er-Gruppen und auf Schlachtfeldern wird sie immer vorgeschlagen, allein nur, solange deine Gesundheit unter 60% liegt"
L["Shows the colored ring around the main icon. The ring is also the swing timer, so hiding it also hides that swing timer (the swing timer bars stay visible)."] = "Zeigt den farbigen Ring um das Hauptsymbol. Der Ring ist auch der Swing-Timer: ausblenden blendet auch diesen Swing-Timer aus (die Swing-Timer-Leisten bleiben sichtbar)."
L["Hide/show the spell name, reason and DPS strip (and the queue in the stacked layout)"] = "Zaubername, Begründung und DPS-Leiste aus-/einblenden (im gestapelten Layout auch die Warteschlange)"

