-- fix_talentrange: gear score label (GS) and auto attack reasons
L["Show your gear score (GS) under the keybind on the rotation icon. GS rates your equipped gear by item level and quality; the colour is its tier (green, blue, purple). Only shown at level 60."] = "Zeigt deinen GearScore (GS) unter der Tastenbelegung auf dem Rotationssymbol. GS bewertet deine angelegte Ausrüstung nach Gegenstandsstufe und Qualität; die Farbe zeigt ihre Stufe (grün, blau, lila). Nur auf Stufe 60 sichtbar."
L["GS"] = "GS"
L["No wand and nothing to cast: melee."] = "Kein Zauberstab und nichts zu wirken: Nahkampf."
L["Start auto attack while energy builds."] = "Automatischen Angriff starten, während sich Energie aufbaut."
L["Closing in - start swinging when it reaches you."] = "Annähern - zuschlagen, sobald es dich erreicht."

-- fix_macros: per-character class macros, Account section, move to character
L["Account (all characters)"] = "Accountweit (alle Charaktere)"
L["Will be saved to General (account) macros"] = "Wird in den allgemeinen Accountmakros gespeichert"
L["Will be saved to Character macros"] = "Wird in Charaktermakros gespeichert"
L["All your characters see this copy. Move it to keep it on this character only."] = "Alle deine Charaktere sehen diese Kopie. Verschiebe sie, um sie nur auf diesem Charakter zu behalten."
L["Move to this character"] = "Zu diesem Charakter verschieben"
L["Moves this macro from the General (account) macros to this character's macros. Other characters lose this macro; put it back on your action bar."] = "Verschiebt dieses Makro aus den allgemeinen Accountmakros in die Makros dieses Charakters. Andere Charaktere verlieren dieses Makro; zieh es wieder auf deine Aktionsleiste."
L["(account macro)"] = "(Accountmakro)"
L["%s moved to this character's macros. Put it back on your action bar."] = "%s wurde in die Makros dieses Charakters verschoben. Zieh es wieder auf deine Aktionsleiste."
L["Could not move %s; nothing was deleted."] = "%s konnte nicht verschoben werden; nichts wurde gelöscht."
L["Your General (account) macros are full (%d). Delete one in the macro window (/macro) first."] = "Deine allgemeinen Accountmakros sind voll (%d). Lösche zuerst eines im Makrofenster (/macro)."
L["Your character macros are full (%d). Delete one in the macro window (/macro) first."] = "Deine Charaktermakros sind voll (%d). Lösche zuerst eines im Makrofenster (/macro)."
L["Use your top trinket (slot 13)"] = "Oberes Schmuckstück benutzen (Platz 13)"
L["Use your bottom trinket (slot 14)"] = "Unteres Schmuckstück benutzen (Platz 14)"
L["Focus your mouseover, else your target"] = "Mouseover als Fokus setzen, sonst dein Ziel"
L["Clear your focus"] = "Fokus löschen"
L["Target what your focus is targeting"] = "Das Ziel deines Fokus anvisieren"
L["Put a Skull on your target (press again to remove it)"] = "Totenschädel auf dein Ziel setzen (erneut drücken zum Entfernen)"
L["Start a ready check (group leader or raid assistant)"] = "Bereitschaftscheck starten (Gruppenleiter oder Schlachtzugsassistent)"
L["Show or hide the LazyGCore rotation display"] = "LazyGCore-Rotationsanzeige ein- oder ausblenden"
L["Reload the user interface"] = "Benutzeroberfläche neu laden"


-- Growth features (Group Sync, share build, welcome tour, version notice)
L["A newer LazyGCore is out (%s) - update on CurseForge."] = "Eine neuere LazyGCore-Version ist erschienen (%s) - aktualisiere sie auf CurseForge."
L["Group Sync is off (Combat settings)."] = "Gruppen-Sync ist aus (Kampf-Einstellungen)."
L["You are not in a group."] = "Du bist in keiner Gruppe."
L["No other LazyGCore users in your group yet."] = "Noch keine anderen LazyGCore-Nutzer in deiner Gruppe."
L["LazyGCore users in your group"] = "LazyGCore-Nutzer in deiner Gruppe"
L["newer"] = "neuer"
L["List the LazyGCore users in your group and their versions"] = "LazyGCore-Nutzer in deiner Gruppe und ihre Versionen auflisten"
L["Group Sync"] = "Gruppen-Sync"
L["LazyGCore users in your party or raid quietly share their addon version, interrupt and big cooldowns over the hidden addon channel: the KICK! box shows who kicks next, and group cooldowns show under the display. Nothing is posted to chat and players without LazyGCore see nothing. Never sent while the game restricts addon messages (boss encounters, PvP)."] = "LazyGCore-Nutzer in deiner Gruppe oder deinem Schlachtzug teilen still über den versteckten Addon-Kanal ihre Addon-Version, ihre Unterbrechung und große Abklingzeiten: Das KICK!-Feld zeigt, wer als Nächstes unterbricht, und Gruppen-Abklingzeiten erscheinen unter der Anzeige. Nichts wird in den Chat geschrieben, und Spieler ohne LazyGCore sehen nichts. Wird nie gesendet, während das Spiel Addon-Nachrichten einschränkt (Bossbegegnungen, PvP)."
L["Show group cooldowns"] = "Gruppen-Abklingzeiten zeigen"
L["Shows a small line under the display when a LazyGCore user in your group uses a big defensive or raid cooldown (Shield Wall, Divine Shield, Innervate, Mana Tide Totem...). Hidden when you are solo. Only applies when Group Sync is on."] = "Zeigt eine kleine Zeile unter der Anzeige, wenn ein LazyGCore-Nutzer in deiner Gruppe eine große Verteidigungs- oder Schlachtzugs-Abklingzeit nutzt (Schildwall, Gottesschild, Anregen, Totem der Manaflut...). Ausgeblendet, wenn du allein bist. Gilt nur, wenn Gruppen-Sync an ist."
L["New version notice"] = "Hinweis auf neue Version"
L["Prints one line in your own chat window, once per session, when a group member runs a newer LazyGCore. Nobody else sees it."] = "Schreibt einmal pro Sitzung eine Zeile in dein eigenes Chatfenster, wenn ein Gruppenmitglied eine neuere LazyGCore-Version nutzt. Niemand sonst sieht sie."
L["You kick next"] = "Du unterbrichst als Nächstes"
L["%s kicks next"] = "%s unterbricht als Nächstes"
L["The welcome tour opens after combat."] = "Die Willkommenstour öffnet sich nach dem Kampf."
L["Replay the short welcome tour"] = "Die kurze Willkommenstour erneut zeigen"
L["Welcome"] = "Willkommen"
L["Your rotation display"] = "Deine Rotationsanzeige"
L["/lazygcore"] = "/lazygcore"
L["This is LazyGCore's display: the big icon is the ability to use next, PREV shows your last casts and NEXT what comes after. A grey icon is out of range or short on mana, the small icon beside it is a cooldown ready to use, and the LazyGCore logo means nothing to press. It shows in combat and when you target an enemy. Drag it to move it."] = "Das ist LazyGCores Anzeige: Das große Symbol ist die Fähigkeit, die du als Nächstes nutzt, ZURÜCK zeigt deine letzten Zauber und WEITER, was danach kommt. Ein graues Symbol ist außer Reichweite oder dir fehlt Mana, das kleine Symbol daneben ist eine bereite Abklingzeit, und das LazyGCore-Logo heißt: gerade nichts zu drücken. Sie erscheint im Kampf und wenn du einen Gegner ins Ziel nimmst. Ziehe sie, um sie zu verschieben."
L["The Talents page shows the next talent of your build and lets you pick another build. While the talent frame is open, your next talent glows."] = "Die Seite Talente zeigt das nächste Talent deines Builds und lässt dich einen anderen Build wählen. Solange das Talentfenster offen ist, leuchtet dein nächstes Talent."
L["Skip tour"] = "Tour überspringen"
L["Next"] = "Weiter"
L["Goes to the next step of the tour."] = "Geht zum nächsten Schritt der Tour."
L["Done"] = "Fertig"
L["Step %d of %d"] = "Schritt %d von %d"
L["Enjoying LazyGCore? A rating on CurseForge helps other players find it."] = "Gefällt dir LazyGCore? Eine Bewertung auf CurseForge hilft anderen Spielern, es zu finden."
L["Click the link, then press Ctrl+C to copy it."] = "Klicke auf den Link und drücke dann Strg+C, um ihn zu kopieren."
L["CurseForge"] = "CurseForge"
L["Say"] = "Sagen"
L["Party"] = "Gruppe"
L["Raid"] = "Schlachtzug"
L["Guild"] = "Gilde"
L["Whisper target"] = "Ziel anflüstern"
L["Whisper"] = "Flüstern an"
L["no player targeted"] = "kein Spieler im Ziel"
L["leveling build"] = "Leveling-Build"
L["PvE build"] = "PvE-Build"
L["PvP build"] = "PvP-Build"
L["You are not in a raid."] = "Du bist in keinem Schlachtzug."
L["You are not in a guild."] = "Du bist in keiner Gilde."
L["Target a player to whisper your build."] = "Nimm einen Spieler ins Ziel, um ihm deinen Build zuzuflüstern."
L["Chat is restricted right now. Try again after the fight."] = "Der Chat ist gerade eingeschränkt. Versuche es nach dem Kampf erneut."
L["Wait a few seconds before sharing again."] = "Warte ein paar Sekunden, bevor du erneut teilst."
L["Could not post the build."] = "Der Build konnte nicht gepostet werden."
L["No talent build to share for this spec."] = "Kein Talent-Build zum Teilen für diese Spezialisierung."
L["Posts to: %s"] = "Postet in: %s"
L["Share build"] = "Build teilen"
L["Post to"] = "Posten in"
L["Where Share build posts your build: Say, Party, Raid, Guild, or a whisper to the player you target."] = "Wohin Build teilen deinen Build postet: Sagen, Gruppe, Schlachtzug, Gilde oder ein Flüstern an den Spieler in deinem Ziel."

