-- Share LazyGCore tab, chat channels, contact links, welcome tour (UI/ShareLazyGCore, UI/Welcome)
L["Other LazyGCore users: %d in your group, %d in your guild"] = "Andere LazyGCore-Nutzer: %d in deiner Gruppe, %d in deiner Gilde"
L["Turn on Share gear score with LazyGCore users (Parsing tab) to see how many players around you use LazyGCore."] = "Schalte GearScore mit LazyGCore-Nutzern teilen (Reiter Parsing) ein, um zu sehen, wie viele Spieler um dich herum LazyGCore nutzen."
L["Follow LazyGCore"] = "Folge LazyGCore"
L["Enjoying LazyGCore? Follow it and add it to your favorites on CurseForge: you hear about every update first, and it helps other players find it."] = "Gefällt dir LazyGCore? Folge ihm und füge es auf CurseForge zu deinen Favoriten hinzu: So erfährst du als Erstes von jedem Update, und andere Spieler finden es leichter."
L["Share LazyGCore"] = "LazyGCore teilen"
L["Know someone who would like LazyGCore? Share it in one click. When your group runs LazyGCore together, Group Sync shows who kicks next."] = "Kennst du jemanden, dem LazyGCore gefallen würde? Teile es mit einem Klick. Wenn deine Gruppe LazyGCore gemeinsam nutzt, zeigt Gruppen-Sync, wer als Nächstes unterbricht."
L["I use LazyGCore Forever for my rotation and talents: it shows what to press next. Free on CurseForge: %s - get it too and Group Sync shows who kicks next!"] = "Ich nutze LazyGCore Forever für Rotation und Talente: Es zeigt, was als Nächstes zu drücken ist. Kostenlos auf CurseForge: %s - hol es dir auch, dann zeigt Gruppen-Sync, wer als Nächstes kickt!"
L["Posts ONE chat line telling your friends about LazyGCore Forever, with the CurseForge link, to the channel picked in Post to. Sent only when you click, never automatically."] = "Postet EINE Chatzeile, die deinen Freunden LazyGCore Forever mit dem CurseForge-Link zeigt, in den unter Posten in gewählten Kanal. Wird nur gesendet, wenn du klickst, nie automatisch."
L["Where Share LazyGCore and Share build post: Say, Party, Raid, Guild, a whisper to the player you target, or a chat channel you have joined (Trade, General, LookingForGroup ...). Public channels: one share a minute."] = "Wohin LazyGCore teilen und Build teilen posten: Sagen, Gruppe, Schlachtzug, Gilde, ein Flüstern an den Spieler in deinem Ziel oder ein Chatkanal, dem du beigetreten bist (Handel, Allgemein, SucheNachGruppe ...). Öffentliche Kanäle: einmal pro Minute."
L["Target a player to whisper the link."] = "Nimm einen Spieler ins Ziel, um ihm den Link zuzuflüstern."
L["Could not post the message."] = "Die Nachricht konnte nicht gepostet werden."
L["Usage: /lazygcore share [say / party / raid / guild / whisper / trade / general / channel number]"] = "Verwendung: /lazygcore share [say / party / raid / guild / whisper / trade / general / Kanalnummer]"
L["Tell your friends about LazyGCore: posts one chat line (say, party, raid, guild, whisper or a chat channel such as trade)"] = "Erzähl deinen Freunden von LazyGCore: postet eine Chatzeile (Sagen, Gruppe, Schlachtzug, Gilde, Flüstern oder ein Chatkanal wie Handel)"
L["You can also type /lazygcore share, or /lazygcore share trade, general, guild, party ..."] = "Du kannst auch /lazygcore share eingeben, oder /lazygcore share trade, general, guild, party ..."
L["Suggestions & bug reports"] = "Vorschläge & Fehlermeldungen"
L["Have an idea, or did LazyGCore suggest something wrong? Tell me on CurseForge: leave a comment on the LazyGCore page or message me on my profile. Include your class, spec and what /lazygcore status prints."] = "Hast du eine Idee, oder hat LazyGCore etwas Falsches vorgeschlagen? Sag es mir auf CurseForge: Hinterlasse einen Kommentar auf der LazyGCore-Seite oder schreib mir über mein Profil. Gib Klasse, Spezialisierung und die Ausgabe von /lazygcore status an."
L["Comments"] = "Kommentare"
L["Comments on the LazyGCore Forever page. Click the link, then press Ctrl+C to copy it."] = "Kommentare auf der Seite von LazyGCore Forever. Klicke auf den Link und drücke dann Strg+C, um ihn zu kopieren."
L["The author's CurseForge profile. Click the link, then press Ctrl+C to copy it."] = "Das CurseForge-Profil des Autors. Klicke auf den Link und drücke dann Strg+C, um ihn zu kopieren."
L["Welcome tour"] = "Willkommenstour"
L["A short tour of the display and every settings tab."] = "Eine kurze Tour durch die Anzeige und jeden Einstellungs-Reiter."
L["Replay The Welcome Tour"] = "Willkommenstour erneut zeigen"
L["Shows the welcome tour again: the display and every settings tab, one step at a time."] = "Zeigt die Willkommenstour erneut: die Anzeige und jeden Einstellungs-Reiter, Schritt für Schritt."
L["not joined"] = "nicht beigetreten"
L["You are not in the %s channel right now (Trade only works in cities)."] = "Du bist gerade nicht im Kanal %s (Handel gibt es nur in Städten)."
L["Public channels: one share a minute. Try again shortly."] = "Öffentliche Kanäle: einmal pro Minute teilen. Versuche es gleich noch einmal."
L["Closes the tour. You can replay it from the Share LazyGCore tab or with /lazygcore tour."] = "Schließt die Tour. Du kannst sie im Reiter LazyGCore teilen oder mit /lazygcore tour erneut abspielen."
L["Goes back to the previous step of the tour."] = "Geht zum vorherigen Schritt der Tour zurück."
L["Turn LazyGCore on or off, lock the display, pick the rotation engine and spec, choose when the display shows, and change its theme, skin and size. Hover over any option to see what it does."] = "LazyGCore an- oder ausschalten, die Anzeige sperren, Empfehlungsquelle und Spezialisierung wählen, festlegen, wann die Anzeige erscheint, und Farbschema, Skin und Größe ändern. Fahre über eine Option, um zu sehen, was sie tut."
L["Everything on the display: the main and cooldown icons, spell history and timeline, the action bar glow and the swing timer."] = "Alles an der Anzeige: Haupt- und Abklingzeit-Symbol, Zauberverlauf und Zeitleiste, das Leuchten auf der Aktionsleiste und der Schlagtimer."
L["What LazyGCore suggests (AoE, defensives, buffs and pets), the KICK!, DEFENSIVE! and PURGE alerts with their sounds, and Group Sync with your group."] = "Was LazyGCore vorschlägt (AoE, Verteidigung, Buffs und Begleiter), die Warnungen KICK!, DEFENSIVE! und PURGE mit ihren Sounds und Gruppen-Sync mit deiner Gruppe."
L["Options for your own class, such as the Warlock curse, Rogue finishers or Mage mana gems."] = "Optionen für deine eigene Klasse, etwa der Hexenmeister-Fluch, Schurken-Finisher oder Manasteine des Magiers."
L["Ready-made macros for your class and spec (PvE and PvP), plus account macros for all your characters. One click creates them."] = "Fertige Makros für deine Klasse und Spezialisierung (PvE und PvP) sowie Account-Makros für alle deine Charaktere. Ein Klick erstellt sie."
L["Your DPS and HPS strip, the Stats window, GearScore, consumables, parse readiness and who else uses LazyGCore."] = "Deine DPS- und HPS-Leiste, das Statistikfenster, GearScore, Verbrauchsgüter, Parse-Bereitschaft und wer sonst noch LazyGCore nutzt."
L["Build your own rotation, exclude spells you never want suggested, and turn LazyGCore off in chosen instances."] = "Baue deine eigene Rotation, schließe Zauber aus, die nie vorgeschlagen werden sollen, und schalte LazyGCore in gewählten Instanzen aus."
L["Update speed, troubleshooting tools and Reset all settings."] = "Aktualisierungsrate, Werkzeuge zur Fehlersuche und Alle Einstellungen zurücksetzen."
L["Save, load, copy and share your settings, or switch profiles automatically per spec."] = "Speichere, lade, kopiere und teile deine Einstellungen oder wechsle Profile automatisch je Spezialisierung."
L["LazyGCore speaks six languages: English, German, Spanish, French, Japanese and Simplified Chinese. Pick one here, or keep Auto."] = "LazyGCore spricht sechs Sprachen: Englisch, Deutsch, Spanisch, Französisch, Japanisch und vereinfachtes Chinesisch. Wähle hier eine oder behalte Auto."
L["What LazyGCore is and how it reads the game on Forever."] = "Was LazyGCore ist und wie es das Spiel auf Forever liest."
L["Type /lazygcore for the settings, /lazygcore help for every command. Replay this tour any time from the Share LazyGCore tab."] = "Gib /lazygcore für die Einstellungen ein, /lazygcore help für alle Befehle. Spiele diese Tour jederzeit im Reiter LazyGCore teilen erneut ab."

-- LazyGCore links (ShareLink)
L["%s Click it with LazyGCore Forever to use it - free on CurseForge: %s"] = "%s Klick ihn mit LazyGCore Forever an, um ihn zu nutzen - kostenlos auf CurseForge: %s"
L["%s %s rotation"] = "%s-%s-Rotation"
L["%s %s %s"] = "%s %s: %s"
L["Before %s's rotation"] = "Vor der Rotation von %s"
L["No rotation to share for this spec."] = "Für diese Spezialisierung gibt es keine Rotation zum Teilen."
L["Share rotation"] = "Rotation teilen"
L["Posts a LazyGCore link to the build your Talent Guide follows, to the channel picked in Post to. Players with LazyGCore click it to follow the same build; everyone else sees where to get LazyGCore. Sent only when you click."] = "Postet einen LazyGCore-Link zu dem Build, dem dein Talentleitfaden folgt, in den unter Posten in gewählten Kanal. Spieler mit LazyGCore klicken darauf, um demselben Build zu folgen; alle anderen sehen, wo es LazyGCore gibt. Wird nur gesendet, wenn du klickst."
L["Posts a LazyGCore link to your rotation for this spec (your custom list, or LazyGCore's default when you have none), to the channel picked in Post to. Players with LazyGCore click it to use it; everyone else sees where to get LazyGCore. Sent only when you click."] = "Postet einen LazyGCore-Link zu deiner Rotation für diese Spezialisierung (deine eigene Liste oder LazyGCores Standard, wenn du keine hast) in den unter Posten in gewählten Kanal. Spieler mit LazyGCore klicken darauf, um sie zu nutzen; alle anderen sehen, wo es LazyGCore gibt. Wird nur gesendet, wenn du klickst."
L["That is your own share."] = "Das ist dein eigener geteilter Link."
L["LazyGCore links open after combat."] = "LazyGCore-Links öffnen sich nach dem Kampf."
L["LazyGCore can't send right now (combat, a boss fight or PvP). Try again in a moment."] = "LazyGCore kann gerade nicht senden (Kampf, Bosskampf oder PvP). Versuche es gleich noch einmal."
L["Already asking for that share..."] = "Frage bereits nach diesem geteilten Link..."
L["That LazyGCore link doesn't work."] = "Dieser LazyGCore-Link funktioniert nicht."
L["Asking %s for their LazyGCore share..."] = "Frage %s nach dem geteilten LazyGCore-Link..."
L["%s didn't answer. They must be online, and a share lasts 2 hours (or until they reload)."] = "%s hat nicht geantwortet. Der Spieler muss online sein, und ein geteilter Link gilt 2 Stunden (oder bis zum Neuladen)."
L["%s's share has expired. Ask them to share it again."] = "Der geteilte Link von %s ist abgelaufen. Bitte darum, ihn erneut zu teilen."
L["%s shared it for another class: it only works for that class."] = "%s hat ihn für eine andere Klasse geteilt: Er funktioniert nur für diese Klasse."
L["%s's share is for a spec LazyGCore doesn't know here."] = "Der geteilte Link von %s ist für eine Spezialisierung, die LazyGCore hier nicht kennt."
L["%s's build isn't in your LazyGCore version. Update LazyGCore and try again."] = "Der Build von %s ist nicht in deiner LazyGCore-Version. Aktualisiere LazyGCore und versuche es erneut."
L["%s's rotation has nothing your LazyGCore can use."] = "Die Rotation von %s enthält nichts, was dein LazyGCore nutzen kann."
L["%s's share couldn't be read."] = "Der geteilte Link von %s konnte nicht gelesen werden."
L["%s shared a %s rotation (%d spells: %s).\n\nUse it as your custom rotation? Your current list is kept as a saved rotation."] = "%s hat eine %s-Rotation geteilt (%d Zauber: %s).\n\nAls deine eigene Rotation verwenden? Deine aktuelle Liste wird als gespeicherte Rotation behalten."
L["Using %s's %s rotation. Change it any time on the Competitive tab."] = "Du nutzt jetzt die Rotation von %s (%s). Ändere sie jederzeit im Reiter Kompetitiv."
L["Use it"] = "Verwenden"
L["%s shared a %s build: %s.\n\nFollow it in your Talent Guide?"] = "%s hat einen %s-Build geteilt: %s.\n\nIn deinem Talentleitfaden folgen?"
L["Your Talent Guide now follows %s's %s build."] = "Dein Talentleitfaden folgt jetzt dem Build von %s (%s)."
L["Follow it"] = "Folgen"
L["Share your rotation and build"] = "Teile deine Rotation und deinen Build"
L["Posts a LazyGCore link to the same channel. Players with LazyGCore click it to use your rotation or follow your talent build; everyone else sees where to get LazyGCore."] = "Postet einen LazyGCore-Link in denselben Kanal. Spieler mit LazyGCore klicken darauf, um deine Rotation zu nutzen oder deinem Talent-Build zu folgen; alle anderen sehen, wo es LazyGCore gibt."
L["Scan with your phone to open LazyGCore Forever on CurseForge."] = "Scanne mit deinem Handy, um LazyGCore Forever auf CurseForge zu öffnen."
L["Point your phone's camera at the code to open LazyGCore Forever on CurseForge."] = "Richte die Kamera deines Handys auf den Code, um LazyGCore Forever auf CurseForge zu öffnen."
L["QR code"] = "QR-Code"
L["Start here: share LazyGCore with friends in one click (party, guild, whisper or a channel like Trade), share your rotation or talent build as a LazyGCore link, send me suggestions or bug reports, and replay this tour."] = "Fang hier an: Teile LazyGCore mit einem Klick mit Freunden (Gruppe, Gilde, Flüstern oder ein Kanal wie Handel), teile deine Rotation oder deinen Talent-Build als LazyGCore-Link, schick mir Vorschläge oder Fehlermeldungen und spiele diese Tour erneut ab."

LazyGCore.Locale:RegisterLocale("deDE", L)

-- 1.0.7 (16 Oct beta build)
L["Arcane Wrath"] = "Arkaner Zorn"
L["Presence of Mind: instant 3.5s Arcane Wrath."] = "Geistesgegenwart: sofortiger Arkaner Zorn statt 3,5 Sek."
L["Your hardest hit: scales with your maximum mana (6s cooldown)."] = "Dein stärkster Treffer: skaliert mit deinem maximalen Mana (6 Sek. Abklingzeit)."
L["Winter's Chill: +40% Cone of Cold damage per stack."] = "Winterkälte: +40% Schaden von Kältekegel pro Stapel."
L["15s: faster Lightning Bolt and Lava Burst, Chain Lightning without a cooldown."] = "15 Sek.: schnellerer Blitzschlag und Lavaeruption, Kettenblitzschlag ohne Abklingzeit."
L["Elemental Mastery: no cooldown on Chain Lightning."] = "Elementarbeherrschung: Kettenblitzschlag ohne Abklingzeit."

-- 1.0.7 (16 Oct beta build)
L["Nothing to press right now - keep attacking."] = "Gerade nichts zu drücken - greif weiter an."
L["Enemy nameplates are off, so LazyGCore can't count the enemies around you and won't suggest AoE spells. Press V or type /lazygcore nameplates to turn them on."] = "Feindliche Namensplaketten sind aus, daher kann LazyGCore die Gegner um dich herum nicht zählen und schlägt keine Flächenzauber vor. Drücke V oder gib /lazygcore nameplates ein, um sie einzuschalten."

-- 1.0.7 (16 Oct beta build)
L["Type /lazygcore reset confirm to reset all settings and reload the UI."] = "Gib /lazygcore reset confirm ein, um alle Einstellungen zurückzusetzen und die Oberfläche neu zu laden."

-- 1.0.7 (16 Oct beta build)
L["Use it on your weapon."] = "Benutze ihn an deiner Waffe."

-- 1.0.7 (16 Oct beta build)
L["Before Demonic Pact: Searing Pain out-damages Shadow Bolt."] = "Vor Dämonischer Pakt: Sengender Schmerz macht mehr Schaden als Schattenblitz."
L["Questing: free damage while you nuke."] = "Beim Questen: kostenloser Schaden, während du zauberst."

-- 1.0.7 (16 Oct beta build)
L["Can't change that in combat."] = "Das kann im Kampf nicht geändert werden."
L["Enemy nameplates are on: LazyGCore can count the enemies around you for AoE."] = "Feindliche Namensplaketten sind an: LazyGCore kann die Gegner um dich herum für Flächenzauber zählen."
L["Turn on enemy nameplates (LazyGCore counts nearby enemies from them for AoE suggestions)"] = "Feindliche Namensplaketten einschalten (LazyGCore zählt daran die Gegner in der Nähe für Flächenvorschläge)"
L["Automatic AoE threshold"] = "Automatische Flächenschwelle"
L["Uses the best number of enemies for your spec, worked out by simulation (for example 2 for cleave specs). Turn it off to set your own number below. Only applies when Enable AoE suggestions is on."] = "Nutzt die beste Gegneranzahl für deine Spezialisierung, per Simulation ermittelt (zum Beispiel 2 für Cleave-Spezialisierungen). Schalte es aus, um unten deine eigene Zahl einzustellen. Gilt nur, wenn AoE-Vorschläge aktivieren an ist."

-- 1.0.7 (16 Oct beta build)
L["Sunder Armor as DPS"] = "Rüstung zerreißen als Schadensverursacher"
L["Arms and Fury: stack Sunder Armor to 5 against elites and in 5-player groups when nobody else applies it (a big damage gain). Leave it off when a tank or another warrior sunders. Never in raids"] = "Waffen und Furor: Rüstung zerreißen gegen Elitegegner und in 5er-Gruppen auf 5 Stapel bringen, wenn es niemand sonst wirkt (deutlich mehr Schaden). Lass es aus, wenn ein Tank oder ein anderer Krieger es wirkt. Nie in Schlachtzügen"
L["Nobody else sunders: armor shred is worth more than your next hit."] = "Niemand sonst zerreißt die Rüstung: der Rüstungsabzug bringt mehr als dein nächster Schlag."

-- 1.0.7 (16 Oct beta build)
L["Improved Scorch: fast crits feed Heating Up."] = "Verbessertes Versengen: schnelle kritische Treffer laden Aufwärmen auf."

-- 1.0.7 (16 Oct beta build)
L["Group: instant, shares Aimed Shot's cooldown."] = "Gruppe: sofort, teilt die Abklingzeit von Gezielter Schuss."

-- 1.0.8
L["Rotation for"] = "Rotation für"
L["Automatic"] = "Automatisch"
L["Open world"] = "Offene Welt"
L["Dungeon"] = "Dungeon"
L["Usage: /lazygcore content auto | world | dungeon | raid"] = "Verwendung: /lazygcore content auto | world | dungeon | raid"
L["Show or set the content the rotation is for: auto, world (questing), dungeon or raid"] = "Zeigt oder setzt, wofür die Rotation gedacht ist: auto, world (Questen), dungeon oder raid"
L["Which rotation to use (this character). Automatic: the open-world questing rotation outside instances, also when you quest in a party, the dungeon rotation in 5-player dungeons and the raid rotation in raids. Pick one to always use it. Also /lazygcore content."] = "Welche Rotation genutzt wird (dieser Charakter). Automatisch: außerhalb von Instanzen die Questrotation der offenen Welt, auch wenn du in einer Gruppe questest, in 5er-Dungeons die Dungeonrotation und in Schlachtzügen die Schlachtzugrotation. Wähle eine, um sie immer zu nutzen. Auch /lazygcore content."

-- 1.0.8
L["Out of mana: drink a mana potion."] = "Kein Mana mehr: trink einen Manatrank."
L["Low health: drink a healing potion."] = "Wenig Gesundheit: trink einen Heiltrank."
L["Potions"] = "Tränke"
L["Shows a mana potion on the cooldown icon once a fight has run you out of mana, and a healing potion below 35% health (the best potion in your bags, when its cooldown is ready)."] = "Zeigt einen Manatrank auf dem Abklingzeit-Symbol, sobald dir in einem Kampf das Mana ausgegangen ist, und einen Heiltrank unter 35% Gesundheit (der beste Trank in deinen Taschen, wenn seine Abklingzeit bereit ist)."
L["Your pet is not happy: feed it for full damage."] = "Dein Begleiter ist nicht zufrieden: füttere ihn für vollen Schaden."

-- 1.0.8
L["Feed Pet"] = "Tier füttern"

-- 1.0.9
L["Playstyle"] = "Spielstil"
L["Efficient"] = "Sparsam"
L["Balanced"] = "Ausgewogen"
L["Max damage"] = "Maximaler Schaden"
L["Questing solo"] = "Solo questen"
L["Questing in a group"] = "Questen in der Gruppe"
L["Usage: /lazygcore style auto | efficient | balanced | max"] = "Verwendung: /lazygcore style auto | efficient | balanced | max"
L["Show or set the playstyle: auto, efficient (save mana and health), balanced or max (most damage)"] = "Spielstil anzeigen oder festlegen: auto, efficient (Mana und Gesundheit sparen), balanced oder max (meisten Schaden)"
L["How hard to push (this character). Efficient: saves mana and health - fewer breaks to drink and eat while questing, more mana left after each pull in groups. Balanced: the fastest leveling counting rest, and steady damage with a mana reserve in groups. Max damage: the most damage now - every mob dies as fast as possible, best for raid bosses and when a healer keeps you up. Automatic: Balanced while questing and in dungeons, Max damage in raids and PvP. Where the simulator found nothing better for your spec, two styles play the same. Also /lazygcore style."] = "Wie stark du drückst (dieser Charakter). Sparsam: spart Mana und Gesundheit - beim Questen weniger Pausen zum Trinken und Essen, in Gruppen mehr Mana nach jedem Pull. Ausgewogen: das schnellste Leveln einschließlich Rast und in Gruppen gleichmäßiger Schaden mit Manareserve. Maximaler Schaden: der meiste Schaden sofort - jeder Gegner stirbt so schnell wie möglich, am besten für Schlachtzugsbosse und wenn ein Heiler dich oben hält. Automatisch: Ausgewogen beim Questen und in Dungeons, Maximaler Schaden in Schlachtzügen und im PvP. Wo der Simulator für deine Spezialisierung nichts Besseres fand, spielen zwei Stile gleich. Auch /lazygcore style."
L["Cheap nuke: more damage per mana here than the DoTs."] = "Günstiger Zauber: hier mehr Schaden pro Mana als die DoTs."
-- 1.1.0 (launch changes)
L["Armor, +3% crit for your party or raid, double Omen procs."] = "Rüstung, +3% Krit für Gruppe oder Schlachtzug, doppelte Omen-Procs."
L["Endgame PvE Cat (0/35/16)"] = "Endgame PvE Katze (0/35/16)"
L["Endgame PvE Bear (0/43/8)"] = "Endgame PvE Bär (0/43/8)"
L["PvP Cat Shifting Power (0/35/16)"] = "PvP Katze Shifting Power (0/35/16)"
L["Leveling 10-60 (6/0/45)"] = "Leveln 10-60 (6/0/45)"
L["Endgame PvE (6/0/45)"] = "Endgame PvE (6/0/45)"
L["Racial: +50% health and mana regeneration for 15s (+100% while Attuned)."] = "Volksfähigkeit: +50% Gesundheits- und Manaregeneration für 15 Sek. (+100% mit Eingestimmt)."
L["Flame Shock (default) / Earth Shock (shift)"] = "Flammenschock (Standard) / Erdschock (Umschalt)"
L["+33% threat - right-click the buff off (you are not tanking)."] = "+33% Bedrohung - Buff per Rechtsklick entfernen (du tankst nicht)."
L["+33% threat, +90% more Holy threat (and Improved Righteous Fury mitigation)."] = "+33% Bedrohung, +90% mehr Heiligbedrohung (und Schadensminderung durch Verbesserter Zorn der Gerechtigkeit)."
L["Oath of Light"] = "Eid des Lichts"
L["Swear it on your tank: your heals on them hit harder (5 min)."] = "Schwöre ihn auf deinen Tank: deine Heilungen auf ihn wirken stärker (5 Min.)."
L["3 swings stored your Seal: swap, the next hit fires them."] = "3 Schläge haben dein Siegel gespeichert: wechseln, der nächste Treffer löst sie aus."
L["Reckless Swings"] = "Rücksichtslose Schwünge"
L["Next 4 swings give 5 extra Rage (costs health)."] = "Die nächsten 4 Schwünge geben 5 Wut extra (kostet Gesundheit)."
L["Lightning Mastery"] = "Blitzbeherrschung"
L["15s: faster Lightning Bolt, Chain Lightning without a cooldown."] = "15 Sek.: schnellerer Blitzschlag, Kettenblitzschlag ohne Abklingzeit."
L["Totemic Call"] = "Totemruf"
L["Leveling 10-60, Cruelty first (34/17/0)"] = "Leveln 10-60, Grausamkeit zuerst (34/17/0)"
L["Endgame PvE Frostfire (0/34/17)"] = "Endgame PvE Frostfeuer (0/34/17)"
L["Leveling AoE grind 10-60 (0/3/48)"] = "Leveln AoE-Grind 10-60 (0/3/48)"
L["Build stacks: +12% of your Intellect as spell damage each, for 18s."] = "Stapel aufbauen: je +12% deiner Intelligenz als Zauberschaden, für 18 Sek."
L["Arcane Blast spell damage is up."] = "Arkanschlag-Zauberschaden ist aktiv."
L["R3 with Ice Shards 5: beats Fireball."] = "Rang 3 mit Eissplitter 5: schlägt Feuerball."
L["Fingers of Frost: x4 damage + Shatter."] = "Frostfinger: x4 Schaden + Zertrümmern."
L["Target is frozen: x4 damage."] = "Ziel ist eingefroren: x4 Schaden."
L["Winter's Chill: +20% Cone of Cold damage per stack."] = "Winterkälte: +20% Kältekegel-Schaden pro Stapel."
L["Shield up before the pull: +15% Frost damage for 1 min."] = "Vor dem Pull Schild hochziehen: +15% Frostschaden für 1 Min."
L["+15% Frost damage for 1 min (+5% while the shield holds)."] = "+15% Frostschaden für 1 Min. (+5%, solange der Schild hält)."
L["Arcane: Arcane Blast stacks to build on elites, bosses, groups and players before Arcane Wrath and Arcane Missiles. Each stack adds 12% of your Intellect as spell damage for 18 seconds from the first Blast, but makes the next Blast cost more (trash always gets one Blast)"] = "Arkan: Arkanschlag-Stapel, die bei Elites, Bossen, in Gruppen und gegen Spieler vor Arkaner Zorn und Arkane Geschosse aufgebaut werden. Jeder Stapel gibt 12% deiner Intelligenz als Zauberschaden für 18 Sekunden ab dem ersten Schlag, verteuert aber den nächsten Schlag (normale Gegner bekommen immer einen Schlag)"
L["Holy Binding: you and the target are both hurt."] = "Heilige Bindung: Du und das Ziel seid beide verletzt."
L["Instant; costs 30% HP if it survives."] = "Spontan; kostet 30% LP, wenn es überlebt."
L["Shank"] = "Shank"
L["Death Mark"] = "Todesmal"
L["Off-hand strike that gives Energy back - use on cooldown."] = "Schlag mit der Nebenhand, der Energie zurückgibt - bei Abklingzeit nutzen."
L["Energy back; with Venom +30% poison damage for 6s."] = "Energie zurück; mit Toxin 6 Sek. lang +30% Giftschaden."
L["Energy back; with Boot Knife +2 CP."] = "Energie zurück; mit Stiefelmesser +2 KP."
L["Stores part of your damage for 6s, then deals it again (bleeds count double)."] = "Speichert 6 Sek. lang einen Teil deines Schadens und verursacht ihn erneut (Blutungen zählen doppelt)."
L["Long fight and Slice and Dice has time left."] = "Langer Kampf und Zerhäckseln läuft noch lange."
L["Improved Ambush crit (or after Ghostly Strike)."] = "Krit durch Verbesserter Hinterhalt (oder nach Geisterhafter Stoß)."
L["Hemorrhage and Serrated Blades boost it."] = "Blutsturz und Gezahnte Klingen verstärken es."
L["Your Rupture and Garrote deal +15% damage."] = "Deine Blutung und dein Erdrosseln verursachen +15% Schaden."
L["+15% dodge (feeds Setup); your next Ambush needs no Stealth."] = "+15% Ausweichen (löst Reinlegen aus); dein nächster Hinterhalt braucht keine Verstohlenheit."
