-- 1.1.0 (launch changes)
L["Dungeons"] = "Dungeons"
L["Raids"] = "Schlachtzüge"
L["LazyGCore's picks"] = "LazyGCores Empfehlungen"
L["LazyGCore's pick for:"] = "LazyGCores Empfehlung für:"
L["Click to follow this build."] = "Klicken, um diesem Build zu folgen."
L["Arms: a two-hander with Sweeping Strikes and Mortal Strike kills fast, and Improved Tactical Mastery keeps your Rage on stance swaps."] = "Waffen: Eine Zweihandwaffe mit Weitreichende Stöße und Tödlicher Stoß tötet schnell, Verbesserte taktische Meisterschaft behält deine Wut beim Haltungswechsel."
L["Groups need tanks: Protection holds packs with Thunder Clap, Shield Slam and Revenge. Go Fury if you join as damage."] = "Gruppen brauchen Tanks: Schutz hält Gruppen mit Donnerknall, Schildschlag und Rache. Geh Furor, wenn du als Schaden mitkommst."
L["Fury: two weapons with Bloodthirst, Flurry and Whirlwind for the most boss damage. Raid tanks stay Protection."] = "Furor: Zwei Waffen mit Blutdurst, Schlaghagel und Wirbelwind für den meisten Bossschaden. Schlachtzugstanks bleiben Schutz."
L["Arms: Mortal Strike halves the healing your target takes - the warrior pick for battlegrounds and duels."] = "Waffen: Tödlicher Stoß halbiert die Heilung deines Ziels - die Kriegerwahl für Schlachtfelder und Duelle."
L["Retribution: Seal of Command and Unsealed Wrath hit hard, and you heal yourself instead of resting."] = "Vergeltung: Siegel des Befehls und Unsealed Wrath treffen hart, und du heilst dich selbst statt zu rasten."
L["Protection: Consecration and Holy Shield hold whole packs. Holy if your group needs a healer."] = "Schutz: Weihe und Heiliger Schild halten ganze Gruppen. Heilig, wenn deine Gruppe einen Heiler braucht."
L["Holy: big, mana-efficient heals on the tanks with Holy Shock and Light's Vigil."] = "Heilig: Große, manasparende Heilungen auf die Tanks mit Heiliger Schock und Light's Vigil."
L["Retribution: Seal of Command bursts and Repentance controls. Holy if you want to heal in battlegrounds."] = "Vergeltung: Siegel des Befehls für Burst und Buße zur Kontrolle. Heilig, wenn du auf Schlachtfeldern heilen willst."
L["Beast Mastery: your pet tanks and Bestial Wrath kills fast - the easiest way to level."] = "Tierherrschaft: Dein Begleiter tankt und Zorn des Wildtiers tötet schnell - der einfachste Weg zu leveln."
L["Marksmanship: steady ranged damage, Trueshot Aura for the group and Barrage on packs."] = "Treffsicherheit: Stetiger Fernkampfschaden, Aura des Volltreffers für die Gruppe und Sperrfeuer gegen Gruppen."
L["Marksmanship: the strongest sustained ranged damage, and Trueshot Aura helps the raid."] = "Treffsicherheit: Der stärkste anhaltende Fernkampfschaden, und Aura des Volltreffers hilft dem Schlachtzug."
L["Survival: Counterattack, Deterrence and Entrapment keep melee off you."] = "Überleben: Gegenangriff, Abschreckung und Einfangen halten Nahkämpfer von dir fern."
L["Combat: Sinister Strike, Shank and Adrenaline Rush with any weapon - fast kills, few deaths."] = "Kampf: Finsterer Stoß, Shank und Adrenalinrausch mit jeder Waffe - schnelle Kills, wenige Tode."
L["Combat: Blade Flurry is the best rogue damage on packs."] = "Kampf: Klingenwirbel ist der beste Schurkenschaden gegen Gruppen."
L["Assassination: Mutilate and the stronger launch poisons for steady boss damage."] = "Meucheln: Verstümmeln und die stärkeren Gifte zum Start für stetigen Bossschaden."
L["Subtlety: Premeditation, Preparation and Death Mark for the hardest openers."] = "Täuschung: Konzentration, Vorbereitung und Todesmal für die härtesten Eröffnungen."
L["Shadow: Spirit Tap, DoTs and Mind Flay - very little drinking between fights."] = "Schatten: Willensentzug, DoTs und Gedankenschinden - zwischen Kämpfen kaum trinken."
L["Holy: Prayer of Healing and Holy Nova keep a whole group up. Discipline works too."] = "Heilig: Gebet der Heilung und Heilige Nova halten eine ganze Gruppe am Leben. Disziplin geht auch."
L["Holy: the strongest group and raid healing."] = "Heilig: Die stärkste Gruppen- und Schlachtzugsheilung."
L["Discipline: Penance, strong shields and Power Infusion. Shadow if you want damage."] = "Disziplin: Sühne, starke Schilde und Seele der Macht. Schatten, wenn du Schaden willst."
L["Enhancement: Stormstrike every 8 seconds with Flurry and Windfury, and you heal yourself between pulls."] = "Verstärkung: Sturmschlag alle 8 Sekunden mit Schlaghagel und Windzorn, und du heilst dich zwischen den Pulls."
L["Restoration: Chain Heal and totems - groups always look for one."] = "Wiederherstellung: Kettenheilung und Totems - Gruppen suchen immer einen."
L["Restoration: Chain Heal and Mana Tide Totem, the shaman role raids want most."] = "Wiederherstellung: Kettenheilung und Totem der Manaflut, die Schamanenrolle, die Schlachtzüge am meisten wollen."
L["Elemental: the stronger launch shocks give big burst. Restoration if you heal."] = "Elementar: Die stärkeren Schocks zum Start geben großen Burst. Wiederherstellung, wenn du heilst."
L["Frost: slows and Frost Nova keep mobs off you; this build pulls whole packs from about 30."] = "Frost: Verlangsamungen und Frostnova halten Gegner fern; dieser Build zieht ab etwa 30 ganze Gruppen."
L["Frost: Blizzard and Cone of Cold on packs, and control when a pull goes wrong."] = "Frost: Blizzard und Kältekegel gegen Gruppen, und Kontrolle, wenn ein Pull schiefgeht."
L["Fire: Ignite and Combustion for the most boss damage."] = "Feuer: Entzünden und Verbrennung für den meisten Bossschaden."
L["Frost: Shatter combos, Ice Block and Ice Barrier."] = "Frost: Zertrümmern-Kombos, Eisblock und Eisbarriere."
L["Affliction: DoTs and drains keep you topped up - almost no downtime."] = "Gebrechen: DoTs und Entzüge halten dich voll - fast keine Pausen."
L["Destruction: Shadow Bolt and Incinerate damage, Rain of Fire on packs."] = "Zerstörung: Schaden durch Schattenblitz und Verbrennen, Feuerregen gegen Gruppen."
L["Destruction: the most single-target damage."] = "Zerstörung: Der meiste Einzelzielschaden."
L["Affliction: DoTs, fears and drains wear players down."] = "Gebrechen: DoTs, Furcht und Entzüge zermürben Spieler."
L["Feral: Cat Form kills fast, Bear Form saves bad pulls, Travel Form between quests."] = "Wildheit: Katzengestalt tötet schnell, Bärengestalt rettet schlechte Pulls, Reisegestalt zwischen Quests."
L["Feral Bear: tanks packs with Swipe and Lacerate. Restoration if you heal."] = "Wildheit Bär: Tankt Gruppen mit Prankenhieb und Aufschlitzen. Wiederherstellung, wenn du heilst."
L["Restoration: HoTs, Wild Growth and Swiftmend - raids always want druid healers."] = "Wiederherstellung: HoTs, Wildwuchs und Rasche Heilung - Schlachtzüge wollen immer Druidenheiler."
L["Feral: shift out of roots and snares. Restoration is a strong battleground healer."] = "Wildheit: Gestaltwandeln befreit von Wurzeln und Verlangsamungen. Wiederherstellung ist ein starker Schlachtfeldheiler."
-- 1.1.0 (launch changes)
L["following"] = "gefolgt"
L["click to follow"] = "zum Folgen klicken"
L["Not sure which build to take? Click the one for what you play next."] = "Unsicher, welchen Build du nehmen sollst? Klicke den für das, was du als Nächstes spielst."
-- 1.1.0 (launch changes)
L["The Talents page shows the next talent of your build and lets you pick another build. LazyGCore's picks tell you the best build for leveling, dungeons, raids and PvP - one click to follow. While the talent frame is open, your next talent glows."] = "Die Talentseite zeigt das nächste Talent deines Builds und lässt dich einen anderen Build wählen. LazyGCores Empfehlungen nennen dir den besten Build fürs Leveln, für Dungeons, Schlachtzüge und PvP - ein Klick zum Folgen. Solange das Talentfenster offen ist, leuchtet dein nächstes Talent."
-- 1.1.0 (launch changes)
L["I use LazyGCore Forever: it shows what to press next, the best talent build for leveling, dungeons, raids and PvP, and ready-made macros. Free on CurseForge: %s"] = "Ich nutze LazyGCore Forever: Es zeigt, was du als Nächstes drücken sollst, den besten Talentbuild fürs Leveln, Dungeons, Schlachtzüge und PvP und fertige Makros. Kostenlos auf CurseForge: %s"
L["Know someone who would like LazyGCore? Share it in one click: what to press next, the best talents for leveling, dungeons, raids and PvP, and ready-made macros."] = "Kennst du jemanden, dem LazyGCore gefallen würde? Teile es mit einem Klick: was als Nächstes zu drücken ist, die besten Talente fürs Leveln, Dungeons, Schlachtzüge und PvP und fertige Makros."
-- 1.1.0 (launch changes)
L["LazyGCore links open after the boss fight."] = "LazyGCore-Links öffnen sich nach dem Bosskampf."
L["LazyGCore links don't work inside battlegrounds and arenas."] = "LazyGCore-Links funktionieren nicht in Schlachtfeldern und Arenen."
L["The game is blocking addon messages right now. Try again in a moment."] = "Das Spiel blockiert gerade Addon-Nachrichten. Versuche es gleich noch einmal."
L["That player is offline, so their share can't be fetched."] = "Dieser Spieler ist offline, daher kann sein Share nicht geladen werden."
L["Too many messages at once. Try again in a few seconds."] = "Zu viele Nachrichten auf einmal. Versuche es in ein paar Sekunden erneut."
L["The game didn't send the request. Try again in a moment."] = "Das Spiel hat die Anfrage nicht gesendet. Versuche es gleich noch einmal."
-- 1.1.0 (launch changes)
L["Tip:"] = "Tipp:"
L["Dual Wield Specialization needs a weapon in your off hand."] = "Beidhändigkeits-Spezialisierung braucht eine Waffe in der Schildhand."
L["Two-Handed Weapon Specialization only works with a two-handed weapon."] = "Zweihandwaffen-Spezialisierung wirkt nur mit einer Zweihandwaffe."
L["Your Protection talents (Bastion, Shield Slam, Defiance) need a shield."] = "Deine Schutz-Talente (Bastion, Schildschlag, Trotz) brauchen einen Schild."
L["Weaponmaster gives no bonus with daggers or fist weapons."] = "Waffenmeister gibt mit Dolchen oder Faustwaffen keinen Bonus."
L["Holy Shield and your Protection talents need a shield."] = "Heiliger Schild und deine Schutz-Talente brauchen einen Schild."
L["Mutilate needs a dagger in each hand."] = "Verstümmeln braucht in jeder Hand einen Dolch."
L["Hemorrhage and Ghostly Strike hit much harder with a dagger in your main hand."] = "Blutsturz und Geisterhafter Stoß treffen mit einem Dolch in der Waffenhand viel härter."
L["Weapon tips"] = "Waffentipps"
L["Out of combat, a soft tip when your weapons don't suit your talents: a two-hander for Two-Handed Weapon Specialization, a shield for Protection, an off-hand weapon for Dual Wield Specialization, daggers for Mutilate. Also one chat line when you equip them. Never during a fight."] = "Außerhalb des Kampfes ein sanfter Hinweis, wenn deine Waffen nicht zu deinen Talenten passen: eine Zweihandwaffe für Zweihandwaffen-Spezialisierung, ein Schild für Schutz, eine Waffe in der Schildhand für Beidhändigkeits-Spezialisierung, Dolche für Verstümmeln. Dazu eine Chatzeile, wenn du sie anlegst. Nie während eines Kampfes."
-- 1.1.0 (launch changes)
L["CD"] = "CD"
L["BUFF"] = "BUFF"
-- 1.1.0 (launch changes)
L["Damage trinket: use it with your cooldowns."] = "Schadens-Schmuckstück: zusammen mit deinen Abklingzeiten nutzen."
L["Shows a ready damage trinket in the cooldown slot in fights worth it (elites, dungeons and raids, players, 3+ enemies) - only trinkets whose use effect adds damage for your spec, never defensive or utility ones. Also your PvP trinket when you are stunned or feared (with Suggest defensives on)."] = "Zeigt ein bereites Schadens-Schmuckstück im Abklingzeit-Platz in Kämpfen, die es wert sind (Elites, Dungeons und Schlachtzüge, Spieler, 3+ Gegner) - nur Schmuckstücke, deren Benutzen-Effekt Schaden für deine Spezialisierung bringt, nie defensive oder nützliche. Außerdem dein PvP-Schmuckstück, wenn du betäubt oder verängstigt bist (mit Defensive vorschlagen an)."
-- 1.1.0 (launch changes)
L["Your swings stored this Seal: swap now, the next hit fires the copies."] = "Deine Schläge haben dieses Siegel gespeichert: jetzt wechseln, der nächste Treffer löst die Kopien aus."
-- 1.1.0 (launch changes)
L["Fury: two one-handers with Bloodthirst, Whirlwind and Flurry kill fastest while leveling. Arms before you can dual wield (20)."] = "Furor: Zwei Einhandwaffen mit Blutdurst, Wirbelwind und Schlaghagel töten beim Leveln am schnellsten. Waffen, bis du beidhändig kämpfen kannst (20)."
-- 1.1.0 (launch changes)
L["Arcane: Arcane Blast stacks with Arcane Power and Presence of Mind - the most boss damage, and mana that lasts the whole fight."] = "Arkan: Arkanschlag-Stapel mit Arkane Macht und Geistesgegenwart - der meiste Bossschaden und Mana für den ganzen Kampf."
-- 1.1.0 (launch changes)
L["Auto: each spec's own choice (Subtlety: Rupture on elites, groups and players; Assassination, Combat and leveling: Eviscerate only). Rupture: Rupture first whenever it is missing on a target above 35% health. Eviscerate: never Rupture"] = "Auto: die Wahl der jeweiligen Spezialisierung (Täuschung: Blutung bei Elites, Gruppen und Spielern; Meucheln, Kampf und Leveln: nur Ausweiden). Blutung: zuerst Blutung, wenn sie auf einem Ziel über 35% Gesundheit fehlt. Ausweiden: nie Blutung"
-- 1.1.0 (launch changes)
L["Show spells on cooldown"] = "Zauber in Abklingzeit zeigen"
L["In combat, when nothing is ready, the main icon shows the next spell that comes off cooldown, greyed out with its cooldown. Off: only spells you can press right now are shown."] = "Wenn im Kampf nichts bereit ist, zeigt das Hauptsymbol den nächsten Zauber, dessen Abklingzeit endet, ausgegraut mit seiner Abklingzeit. Aus: nur Zauber, die du jetzt drücken kannst, werden gezeigt."
L["'Nothing to press' in combat"] = "'Nichts zu drücken' im Kampf"
L["In combat, when there is nothing to press right now, the main icon shows the LazyGCore logo and 'Nothing to press right now - keep attacking.' Off: the icon and the text stay empty instead."] = "Wenn es im Kampf gerade nichts zu drücken gibt, zeigt das Hauptsymbol das LazyGCore-Logo und 'Gerade nichts zu drücken - weiter angreifen.' Aus: Symbol und Text bleiben stattdessen leer."
-- 1.1.3 (Warlock raid gear option)
L["Raid Gear"] = "Raid-Ausrüstung"
L["Full raid gear rotation"] = "Rotation für volle Raid-Ausrüstung"
L["Dungeons and raids only. Demonology skips Demonic Brand and the Decimation Soul Fire; Destruction skips Corruption on single targets. In full raid gear this is about 2% more damage on raid bosses, but less in pre-raid gear, so it is off by default"] = "Nur in Dungeons und Raids. Dämonologie lässt Dämonisches Brandmal und das Seelenfeuer durch Dezimierung weg; Zerstörung lässt Verderbnis auf einzelnen Zielen weg. In voller Raid-Ausrüstung etwa 2% mehr Schaden an Raidbossen, in Pre-Raid-Ausrüstung aber weniger, daher standardmäßig aus"
-- 1.1.3 (welcome tour: your class)
L["LazyGCore for your %s"] = "LazyGCore für die Klasse %s"
L["LazyGCore knows every spec of your class: the rotation, your buffs and reminders, and the talents that change what it suggests."] = "LazyGCore kennt jede Spezialisierung deiner Klasse: die Rotation, deine Buffs und Erinnerungen und die Talente, die ändern, was es vorschlägt."
L["LazyGCore plays Arms, Fury and Protection with you: Sunder Armor stacks, Heroic Strike when you have rage to spare, threat when you tank, and Battle Shout kept up. It tips you when your weapon does not suit your talents, and LazyGCore's picks show the best build for leveling, dungeons, raids and PvP."] = "LazyGCore spielt Waffen, Furor und Schutz mit dir: Rüstung zerreißen-Stapel, Heldenhafter Stoß bei überschüssiger Wut, Bedrohung beim Tanken und Schlachtruf immer aktiv. Es gibt dir Tipps, wenn deine Waffe nicht zu deinen Talenten passt, und LazyGCores Empfehlungen zeigen den besten Build fürs Leveln, Dungeons, Raids und PvP."
L["LazyGCore plays Retribution, Protection and Holy with you: Seals and Judgements in the right order, Holy Shield and Consecration when you tank, and for Holy a heal target picked from your party or raid, plus Cleanse when someone has a debuff you can remove. It reminds you of your Blessing and tips you when your weapon does not suit your talents."] = "LazyGCore spielt Vergeltung, Schutz und Heilig mit dir: Siegel und Richturteile in der richtigen Reihenfolge, Heiliger Schild und Weihe beim Tanken und für Heilig ein Heilziel aus deiner Gruppe oder deinem Raid, dazu Reinigung des Glaubens, wenn jemand einen entfernbaren Debuff hat. Es erinnert dich an deinen Segen und gibt Tipps, wenn deine Waffe nicht zu deinen Talenten passt."
L["LazyGCore plays Beast Mastery, Marksmanship and Survival with you: Hunter's Mark, Serpent Sting, Aimed Shot, Multi-Shot and your Hawks at the right time, and what to do when a mob reaches melee range. It reminds you about your pet and Mend Pet, and keeps the right Aspect up."] = "LazyGCore spielt Tierherrschaft, Treffsicherheit und Überleben mit dir: Mal des Jägers, Schlangenbiss, Gezielter Schuss, Mehrfachschuss und deine Falken zur richtigen Zeit und was zu tun ist, wenn ein Gegner in Nahkampfreichweite kommt. Es erinnert dich an dein Tier und Tier heilen und hält den richtigen Aspekt aktiv."
L["LazyGCore plays Assassination, Combat and Subtlety with you: it builds combo points and picks the finisher - Slice and Dice, Rupture or Eviscerate - at the number of points you choose. It reminds you to apply poisons, can suggest Vanish for damage, and tips you when your weapons do not suit your talents."] = "LazyGCore spielt Meucheln, Kampf und Täuschung mit dir: Es baut Combopunkte auf und wählt den Finisher - Zerhäckseln, Blutung oder Ausweiden - bei der Punktzahl, die du festlegst. Es erinnert dich an Gifte, kann Verschwinden für Schaden vorschlagen und gibt Tipps, wenn deine Waffen nicht zu deinen Talenten passen."
L["LazyGCore plays Shadow, Holy and Discipline with you. Shadow: Shadow Word: Pain, Mind Blast and Mind Flay in the right order, Shadow Word: Death at the health you choose, and Vampiric Embrace in raids. Holy and Discipline: a heal target picked from your party or raid and the right heal for it. It keeps Inner Fire and your buffs up."] = "LazyGCore spielt Schatten, Heilig und Disziplin mit dir. Schatten: Schattenwort: Schmerz, Gedankenschlag und Gedankenschinden in der richtigen Reihenfolge, Schattenwort: Tod bei der Gesundheit, die du wählst, und Vampirumarmung in Raids. Heilig und Disziplin: ein Heilziel aus deiner Gruppe oder deinem Raid und die passende Heilung dafür. Es hält Inneres Feuer und deine Buffs aktiv."
L["LazyGCore plays Elemental, Enhancement and Restoration with you: totems (Call of the Elements before dungeon and raid pulls), your weapon imbue and Water or Lightning Shield kept up, and for Restoration a heal target picked from your party or raid, with Chain Heal when several people are hurt."] = "LazyGCore spielt Elementar, Verstärkung und Wiederherstellung mit dir: Totems (Ruf der Elemente vor Pulls in Dungeons und Raids), deine Waffenverzauberung und Wasser- oder Blitzschlagschild immer aktiv, und für Wiederherstellung ein Heilziel aus deiner Gruppe oder deinem Raid, mit Kettenheilung, wenn mehrere verletzt sind."
L["LazyGCore plays Arcane, Fire and Frost with you: Arcane Blast stacks, Scorch stacks for Fire, and your procs. It watches your mana with Mana Gems and Evocation, keeps Arcane Intellect and your armor up, tips you when your weapon does not suit your talents, and the cooldown icon shows when burst cooldowns and damage trinkets are ready."] = "LazyGCore spielt Arkan, Feuer und Frost mit dir: Arkanschlag-Stapel, Versengen-Stapel für Feuer und deine Procs. Es achtet mit Manasteinen und Hervorrufung auf dein Mana, hält Arkane Intelligenz und deine Rüstung aktiv, gibt Tipps, wenn deine Waffe nicht zu deinen Talenten passt, und das Abklingzeit-Symbol zeigt, wann Burst-Abklingzeiten und Schadensschmuckstücke bereit sind."
L["LazyGCore plays Affliction, Demonology and Destruction with you: your Curse and Bane, Corruption and Immolate refreshed at the right time, and the filler that suits your talents. It suggests Life Tap when you run low on mana, reminds you to summon your demon and keep Demon Armor and your weapon stone up, and suggests Health Funnel when your demon is hurt."] = "LazyGCore spielt Gebrechen, Dämonologie und Zerstörung mit dir: dein Fluch und Bann, Verderbnis und Feuerbrand zur richtigen Zeit erneuert und der Füller, der zu deinen Talenten passt. Es schlägt Aderlass vor, wenn dir das Mana ausgeht, erinnert dich, deinen Dämon zu beschwören und Dämonenrüstung und deinen Waffenstein aktiv zu halten, und schlägt Lebenslinie vor, wenn dein Dämon verletzt ist."
L["LazyGCore follows your form: Balance with Moonkin Form, Faerie Fire, Moonfire and Insect Swarm; Feral as a cat for damage or a bear for tanking; Restoration with a heal target picked from your party or raid and Rejuvenation kept rolling. It keeps Mark of the Wild and Thorns up."] = "LazyGCore folgt deiner Gestalt: Gleichgewicht mit Moonkingestalt, Feenfeuer, Mondfeuer und Insektenschwarm; Wilder Kampf als Katze für Schaden oder als Bär zum Tanken; Wiederherstellung mit einem Heilziel aus deiner Gruppe oder deinem Raid und Verjüngung immer aktiv. Es hält Mal der Wildnis und Dornen aktiv."

-- 1.1.4 (keybind size)
L["Custom keybind size"] = "Eigene Tastenbelegung-Größe"
L["Lets you change the size of the keybind text on the main icon with Keybind Size. Off: the normal size that follows the icon size. Only applies when Show keybind is on."] = "Damit kannst du die Größe der Tastenbelegung auf dem Hauptsymbol mit Tastenbelegung-Größe ändern. Aus: die normale Größe, die sich nach der Symbolgröße richtet. Gilt nur, wenn Tastenbelegung anzeigen an ist."
L["Keybind Size"] = "Tastenbelegung-Größe"
L["Size of the keybind text compared to normal (1.50 = 50% bigger). Up to 4 fills the whole icon; a big keybind moves to the centre. It never grows past the icon: a long keybind shrinks to fit. Only applies when Custom keybind size is on."] = "Größe der Tastenbelegung im Vergleich zu normal (1.50 = 50% größer). Bis 4 füllt sie das ganze Symbol; eine große Tastenbelegung rückt in die Mitte. Sie wird nie größer als das Symbol: eine lange Tastenbelegung wird passend verkleinert. Gilt nur, wenn Eigene Tastenbelegung-Größe an ist."

-- 1.1.5 (talent pick order)
L["Show the pick order on the talent frame"] = "Reihenfolge im Talentfenster anzeigen"
L["Puts a number on every talent of your build that still needs points, in the order to take them (1 = next), on all trees, even when you have no point to spend."] = "Setzt eine Zahl auf jedes Talent deines Builds, das noch Punkte braucht, in der Reihenfolge, in der du sie nehmen solltest (1 = als Nächstes), in allen Bäumen, auch wenn du keinen Punkt frei hast."
L["Pick numbers"] = "Reihenfolge-Zahlen"
L["How many upcoming talents get a number: the whole build (default) or only the next 3, 5 or 10. Only applies when Show the pick order on the talent frame is on."] = "Wie viele kommende Talente eine Zahl bekommen: der ganze Build (Standard) oder nur die nächsten 3, 5 oder 10. Gilt nur, wenn Reihenfolge im Talentfenster anzeigen an ist."
L["Whole build"] = "Ganzer Build"
L["Next 3"] = "Nächste 3"
L["Next 5"] = "Nächste 5"
L["Next 10"] = "Nächste 10"
